export function computeCompletedGraphPlanHashV3(
  plan: Readonly<CompletedGraphPlanContractV1>,
): EvmBytes32V1 {
  assertCompletedGraphPlanContractV1(plan);
  const identities = plan.identities;
  const abiEncodedPlanHash = keccakWordsV3([
    bytes32WordV3(plan.profileKey, "plan.profileKey"),
    bytes32WordV3(plan.profileDescriptorHash, "plan.profileDescriptorHash"),
    bytes32WordV3(plan.exactContractBindingHash, "plan.exactContractBindingHash"),
    bytes32WordV3(plan.routeSchemaHash, "plan.routeSchemaHash"),
    bytes32WordV3(plan.planSchemaArtifactHash, "plan.planSchemaArtifactHash"),
    bytes32WordV3(plan.sourceRepositoryHash, "plan.sourceRepositoryHash"),
    gitObjectWordV3(plan.sourceCommitId, "plan.sourceCommitId"),
    gitObjectWordV3(plan.sourceTreeId, "plan.sourceTreeId"),
    bytes32WordV3(plan.sourceLaunchId, "plan.sourceLaunchId"),
    bytes32WordV3(plan.manifestHash, "plan.manifestHash"),
    bytes32WordV3(plan.policyHash, "plan.policyHash"),
    bytes32WordV3(plan.revenueBindingHash, "plan.revenueBindingHash"),
    bytes32WordV3(plan.compilerArtifactHash, "plan.compilerArtifactHash"),
    bytes32WordV3(plan.applicantPlanArtifactHash, "plan.applicantPlanArtifactHash"),
    bytes32WordV3(plan.adoptionIntentHash, "plan.adoptionIntentHash"),
    uintWordV3(String(plan.executionReadiness), 8, "plan.executionReadiness"),
    bytes32WordV3(plan.executionReadinessConstraintHash,
      "plan.executionReadinessConstraintHash"),
    uintWordV3(String(plan.executionTimeConstraint), 8, "plan.executionTimeConstraint"),
    bytes32WordV3(plan.executionTimeConstraintEvidenceHash,
      "plan.executionTimeConstraintEvidenceHash"),
    addressWordV3(plan.launchWallet, "plan.launchWallet"),
    uintWordV3(String(plan.launchClassification), 8, "plan.launchClassification"),
    uintWordV3(String(plan.identityMask), 16, "plan.identityMask"),
    addressWordAllowZeroV3(identities.token, "plan.identities.token"),
    addressWordAllowZeroV3(identities.hook, "plan.identities.hook"),
    addressWordAllowZeroV3(identities.nft, "plan.identities.nft"),
    bytes32WordV3(identities.applicationHash, "plan.identities.applicationHash"),
    bytes32WordV3(plan.componentGraphHash, "plan.componentGraphHash"),
    bytes32WordV3(plan.exactRuntimeSetHash, "plan.exactRuntimeSetHash"),
    bytes32WordV3(plan.componentConfigurationSetHash,
      "plan.componentConfigurationSetHash"),
    bytes32WordV3(plan.configurationHash, "plan.configurationHash"),
    addressWordAllowZeroV3(plan.poolManager, "plan.poolManager"),
    bytes32WordV3(plan.poolManagerRuntimeCodeHash, "plan.poolManagerRuntimeCodeHash"),
    uintWordV3(String(plan.poolManagerComponentIndex), 8,
      "plan.poolManagerComponentIndex"),
    bytes32WordV3(plan.poolId, "plan.poolId"),
    bytes32WordV3(plan.poolKeyHash, "plan.poolKeyHash"),
    bytes32WordV3(plan.poolResultHash, "plan.poolResultHash"),
    bytes32WordV3(plan.architectureResultHash, "plan.architectureResultHash"),
    bytes32WordV3(plan.deploymentLineageHash, "plan.deploymentLineageHash"),
    bytes32WordV3(plan.resultHash, "plan.resultHash"),
  ]);
  return keccakWordsV3([
    typehash("plan"),
    bytes32WordV3(abiEncodedPlanHash, "plan ABI hash"),
  ]);
}

export function assertCompletedGraphPlanContractV1(
  raw: unknown,
): asserts raw is CompletedGraphPlanContractV1 {
  const plan = plainRecord(raw, "CompletedGraphPlanV1");
  exactKeys(plan, [
    "profileKey", "profileDescriptorHash", "exactContractBindingHash", "routeSchemaHash",
    "planSchemaArtifactHash", "sourceRepositoryHash", "sourceCommitId", "sourceTreeId",
    "sourceLaunchId", "manifestHash", "policyHash", "revenueBindingHash",
    "compilerArtifactHash", "applicantPlanArtifactHash", "adoptionIntentHash",
    "executionReadiness", "executionReadinessConstraintHash", "executionTimeConstraint",
    "executionTimeConstraintEvidenceHash", "launchWallet", "launchClassification",
    "identityMask", "identities", "componentGraphHash", "exactRuntimeSetHash",
    "componentConfigurationSetHash", "configurationHash", "poolManager",
    "poolManagerRuntimeCodeHash", "poolManagerComponentIndex", "poolId", "poolKeyHash",
    "poolResultHash", "architectureResultHash", "deploymentLineageHash", "resultHash",
  ], "CompletedGraphPlanV1");
  for (const key of [
    "profileKey", "profileDescriptorHash", "exactContractBindingHash", "routeSchemaHash",
    "planSchemaArtifactHash", "sourceRepositoryHash", "sourceLaunchId", "manifestHash",
    "policyHash", "revenueBindingHash", "compilerArtifactHash", "applicantPlanArtifactHash",
    "adoptionIntentHash", "executionReadinessConstraintHash",
    "executionTimeConstraintEvidenceHash", "componentGraphHash", "exactRuntimeSetHash",
    "componentConfigurationSetHash", "configurationHash", "poolManagerRuntimeCodeHash",
    "poolId", "poolKeyHash", "poolResultHash", "architectureResultHash",
    "deploymentLineageHash", "resultHash",
  ]) bytes32WordV3(plan[key], `plan.${key}`);
  gitObjectWordV3(plan.sourceCommitId, "plan.sourceCommitId");
  gitObjectWordV3(plan.sourceTreeId, "plan.sourceTreeId");
  if (plan.executionReadiness !== 1
    || plan.executionReadinessConstraintHash
      !== PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1
        .canonicalConstants.adoptionOnlyReadinessConstraintHash
    || !isExactExecutionTimeBindingV3(
      plan.executionTimeConstraint,
      plan.executionTimeConstraintEvidenceHash,
    )
    || plan.revenueBindingHash !== ZERO_BYTES32) {
    throw new TypeError("CompletedGraphPlanV1 is not exact ADOPT-only zero-revenue authority");
  }
  addressWordV3(plan.launchWallet, "plan.launchWallet");
  if (plan.launchClassification !== 1 && plan.launchClassification !== 2) {
    throw new TypeError("CompletedGraphPlanV1 launch classification is unsupported");
  }
  if (!Number.isInteger(plan.identityMask)) {
    throw new TypeError("CompletedGraphPlanV1 identity mask must be an integer number");
  }
  const identityMask = uintValueV3(String(plan.identityMask), 16, "plan.identityMask");
  if (identityMask === 0n || (identityMask & ~31n) !== 0n) {
    throw new TypeError("CompletedGraphPlanV1 identity mask is empty or has unknown bits");
  }
  const identities = plainRecord(plan.identities, "plan.identities");
  exactKeys(identities, ["token", "hook", "nft", "applicationHash"], "plan.identities");
  addressWordAllowZeroV3(identities.token, "plan.identities.token");
  addressWordAllowZeroV3(identities.hook, "plan.identities.hook");
  addressWordAllowZeroV3(identities.nft, "plan.identities.nft");
  bytes32WordV3(identities.applicationHash, "plan.identities.applicationHash");
  const identityPresence = [identities.token, identities.hook, identities.nft].map(
    (value) => value !== `0x${"0".repeat(40)}`,
  );
  identityPresence.push(identities.applicationHash !== ZERO_BYTES32);
  identityPresence.forEach((present, index) => {
    if (((identityMask & (1n << BigInt(index))) !== 0n) !== present) {
      throw new TypeError("CompletedGraphPlanV1 identity mask does not match primary identities");
    }
  });
  addressWordAllowZeroV3(plan.poolManager, "plan.poolManager");
  uintWordV3(String(plan.poolManagerComponentIndex), 8,
    "plan.poolManagerComponentIndex");
  const hasPool = (identityMask & 16n) !== 0n;
  const completePool = plan.poolManager !== `0x${"0".repeat(40)}`
    && plan.poolManagerRuntimeCodeHash !== ZERO_BYTES32 && plan.poolId !== ZERO_BYTES32
    && plan.poolKeyHash !== ZERO_BYTES32 && plan.poolResultHash !== ZERO_BYTES32;
  if (hasPool !== completePool || (!hasPool && plan.poolManagerComponentIndex !== 0)) {
    throw new TypeError("CompletedGraphPlanV1 pool identity binding is incomplete");
  }
}

export function createSourceIdentityReferentsV3(input: Readonly<{
  readonly applicantRequest: SourceIdentityReferentsV3["applicantRequest"];
  readonly executableEvidenceSource: Omit<
    SourceIdentityReferentsV3["executableEvidenceSource"], "sourceCommitHash" | "sourceTreeHash"
  >;
  readonly carrierEvidenceProvenance:
    SourceIdentityReferentsV3["carrierEvidenceProvenance"];
}>): Readonly<SourceIdentityReferentsV3> {
  const source = input.executableEvidenceSource;
  const core = {
    schemaVersion: "programmable.router-v2-source-identity-referents.v3",
    applicantRequest: input.applicantRequest,
    executableEvidenceSource: {
      ...source,
      sourceCommitHash: computeCompletedGraphSourceCommitHashV3(source.sourceCommitId),
      sourceTreeHash: computeCompletedGraphSourceTreeHashV3(source.sourceTreeId),
    },
    carrierEvidenceProvenance: input.carrierEvidenceProvenance,
    referentPolicy:
      "A_APPLICANT_REQUEST_B_EXECUTABLE_SOURCE_C_CARRIER_NEVER_SUBSTITUTABLE",
  } as const;
  const result = deepFreeze({ ...core, referentsHash: canonicalSha256(
    "programmable.router-v2-source-identity-referents.v3", core,
  ) });
  assertSourceIdentityReferentsV3(result);
  return result;
}

export function computeExecutableSourceRepositoryHashV3(
  sourceRepository: string,
): EvmBytes32V1 {
  if (typeof sourceRepository !== "string" || sourceRepository.length === 0
    || sourceRepository !== sourceRepository.trim()) {
    throw new TypeError("Executable-source repository must be a canonical nonempty string");
  }
  let parsed: URL;
  try {
    parsed = new URL(sourceRepository);
  } catch {
    throw new TypeError("Executable-source repository must be an absolute canonical URL");
  }
  if (parsed.protocol !== "https:" || parsed.username !== "" || parsed.password !== ""
    || parsed.search !== "" || parsed.hash !== "" || parsed.toString() !== sourceRepository) {
    throw new TypeError("Executable-source repository URL is not canonical HTTPS identity");
  }
  return createSha256ToEvmBytes32BindingV1(canonicalSha256(
    "programmable.router-v2-executable-source-repository.v3", { sourceRepository },
  )).evmBytes32;
}

export function assertSourceIdentityReferentsV3(
  raw: unknown,
): asserts raw is SourceIdentityReferentsV3 {
  const value = plainRecord(raw, "V3 source identity referents");
  exactKeys(value, [
    "schemaVersion", "applicantRequest", "executableEvidenceSource",
    "carrierEvidenceProvenance", "referentPolicy", "referentsHash",
  ], "V3 source identity referents");
  if (value.schemaVersion !== "programmable.router-v2-source-identity-referents.v3"
    || value.referentPolicy
      !== "A_APPLICANT_REQUEST_B_EXECUTABLE_SOURCE_C_CARRIER_NEVER_SUBSTITUTABLE") {
    throw new TypeError("V3 source referent policy drifted");
  }
  const applicant = plainRecord(value.applicantRequest, "applicant/request referent A");
  exactKeys(applicant, [
    "applicantIdHash", "reviewerAttestationHash", "reviewAdmissionHash", "requestReceiptHash",
  ], "applicant/request referent A");
  bytes32(applicant.applicantIdHash, "referent A applicantIdHash");
  bytes32(applicant.reviewerAttestationHash, "referent A reviewerAttestationHash");
  sha256(applicant.reviewAdmissionHash, "referent A reviewAdmissionHash");
  sha256(applicant.requestReceiptHash, "referent A requestReceiptHash");
  const source = plainRecord(value.executableEvidenceSource, "executable-source referent B");
  exactKeys(source, [
    "sourceRepository", "sourceRepositoryHash", "sourceCommitId", "sourceTreeId",
    "sourceCommitHash", "sourceTreeHash", "sourceHeadCommit", "sourceLaunchId",
  ], "executable-source referent B");
  if (typeof source.sourceRepository !== "string" || source.sourceRepository.length === 0) {
    throw new TypeError("Executable-source referent B repository is missing");
  }
  bytes32(source.sourceRepositoryHash, "referent B sourceRepositoryHash");
  if (source.sourceRepositoryHash
      !== computeExecutableSourceRepositoryHashV3(source.sourceRepository)) {
    throw new TypeError("Executable-source referent B repository commitment drifted");
  }
  const commit = gitObjectId(source.sourceCommitId, "referent B sourceCommitId");
  const tree = gitObjectId(source.sourceTreeId, "referent B sourceTreeId");
  const head = gitObjectId(source.sourceHeadCommit, "referent B sourceHeadCommit");
  if (head !== commit) {
    throw new TypeError("Executable-source head must equal the exact reviewed executable commit");
  }
  bytes32(source.sourceLaunchId, "referent B sourceLaunchId");
  if (source.sourceCommitHash !== computeCompletedGraphSourceCommitHashV3(commit)
    || source.sourceTreeHash !== computeCompletedGraphSourceTreeHashV3(tree)) {
    throw new TypeError("Executable-source referent B Git commitment drifted");
  }
  const carrier = plainRecord(value.carrierEvidenceProvenance, "carrier referent C");
  exactKeys(carrier, [
    "builderEvidenceHash", "carrierArtifactSha256", "carrierCommit", "carrierTree",
  ], "carrier referent C");
  bytes32(carrier.builderEvidenceHash, "referent C builderEvidenceHash");
  sha256(carrier.carrierArtifactSha256, "referent C carrier artifact");
  if ((carrier.carrierCommit === null) !== (carrier.carrierTree === null)) {
    throw new TypeError("Carrier referent C commit/tree provenance must be paired");
  }
  if (carrier.carrierCommit !== null) {
    gitObjectId(carrier.carrierCommit, "referent C carrierCommit");
    gitObjectId(carrier.carrierTree, "referent C carrierTree");
  }
  sha256(value.referentsHash, "source referents hash");
  const { referentsHash: _referentsHash, ...core } = value;
  if (value.referentsHash !== canonicalSha256(
    "programmable.router-v2-source-identity-referents.v3", core,
  )) throw new TypeError("V3 source referents hash drifted");
}

export function assertApplicantLaunchPlanV3(
  descriptor: Readonly<LaunchProfileDescriptorV3>,
  raw: unknown,
): asserts raw is ApplicantLaunchPlanV3 {
  assertLaunchProfileDescriptorV3(descriptor);
  if (descriptor.architecture !== "COMPLETED_GRAPH_ADOPTION"
    || descriptor.contractArtifactBinding === null
    || descriptor.contractArtifactBindingHash === null) {
    throw new TypeError("V3 completed-graph plan requires the frozen ADOPT artifact descriptor");
  }
  const value = plainRecord(raw, "V3 applicant launch plan");
  exactKeys(value, [
    "schemaVersion", "planVersion", "legacyPlan", "legacyPlanHash",
    "legacyMigrationRule", "profileDescriptorHash", "contractArtifactBindingHash",
    "sourceReferents", "contractPlan", "contractPlanHash", "sourceLaunchId", "issuedAt",
    "planHash",
  ], "V3 applicant launch plan");
  if (value.schemaVersion !== "programmable.router-v2-applicant-launch-plan.v3"
    || value.planVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3
    || value.legacyMigrationRule !== "V2_ARCHIVAL_ONLY_EXPLICIT_V3_CONTRACT_FIELDS_CONTROL") {
    throw new TypeError("V3 applicant launch plan version or migration domain drifted");
  }
  const legacy = assertApplicantLaunchPlanV2(
    descriptor.legacyDescriptor,
    value.legacyPlan as ApplicantLaunchPlanV2,
  );
  const source = value.sourceReferents as SourceIdentityReferentsV3;
  const contractPlan = value.contractPlan as CompletedGraphPlanContractV1;
  assertSourceIdentityReferentsV3(source);
  assertCompletedGraphPlanContractV1(contractPlan);
  if (value.legacyPlanHash !== legacy.planHash
    || value.profileDescriptorHash !== descriptor.descriptorHash
    || value.contractArtifactBindingHash !== descriptor.contractArtifactBindingHash
    || contractPlan.exactContractBindingHash
      !== createSha256ToEvmBytes32BindingV1(
        PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1.artifactBindingHash,
      ).evmBytes32
    || contractPlan.profileDescriptorHash
      !== createSha256ToEvmBytes32BindingV1(descriptor.descriptorHash).evmBytes32
    || value.contractPlanHash !== computeCompletedGraphPlanHashV3(contractPlan)
    || value.sourceLaunchId !== contractPlan.sourceLaunchId
    || contractPlan.sourceRepositoryHash
      !== source.executableEvidenceSource.sourceRepositoryHash
    || contractPlan.sourceCommitId !== source.executableEvidenceSource.sourceCommitId
    || contractPlan.sourceTreeId !== source.executableEvidenceSource.sourceTreeId
    || contractPlan.sourceLaunchId !== source.executableEvidenceSource.sourceLaunchId) {
    throw new TypeError("V3 applicant launch plan crossed source, profile or Contract identity");
  }
  sha256(value.planHash, "V3 applicant plan hash");
  const { planHash: _planHash, ...core } = value;
  if (value.planHash !== canonicalSha256(
    "programmable.router-v2-applicant-launch-plan.v3", core,
  )) throw new TypeError("V3 applicant launch plan hash drifted");
}

export function assertBuilderEvidenceCommitmentV3(
  descriptor: Readonly<LaunchProfileDescriptorV3>,
  plan: Readonly<ApplicantLaunchPlanV3>,
  raw: unknown,
): asserts raw is BuilderEvidenceCommitmentV3 {
  assertApplicantLaunchPlanV3(descriptor, plan);
  const value = plainRecord(raw, "V3 builder evidence commitment");
  exactKeys(value, [
    "schemaVersion", "evidenceVersion", "legacyEvidence", "legacyEvidenceHash",
    "profileDescriptorHash", "planHash", "contractArtifactBindingHash",
    "contractPlanHash", "sourceReferents", "contractBuilderEvidenceHash", "issuedAt",
    "evidenceHash",
  ], "V3 builder evidence commitment");
  if (value.schemaVersion !== "programmable.router-v2-builder-evidence-commitment.v3"
    || value.evidenceVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3) {
    throw new TypeError("V3 builder evidence version drifted");
  }
  const legacy = assertBuilderEvidenceCommitmentV2(
    descriptor.legacyDescriptor,
    plan.legacyPlan,
    value.legacyEvidence as BuilderEvidenceCommitmentV2,
  );
  const source = value.sourceReferents as SourceIdentityReferentsV3;
  assertSourceIdentityReferentsV3(source);
  if (value.legacyEvidenceHash !== legacy.evidenceHash
    || value.profileDescriptorHash !== descriptor.descriptorHash
    || value.planHash !== plan.planHash
    || value.contractArtifactBindingHash !== plan.contractArtifactBindingHash
    || value.contractPlanHash !== plan.contractPlanHash
    || source.referentsHash !== plan.sourceReferents.referentsHash
    || value.contractBuilderEvidenceHash
      !== source.carrierEvidenceProvenance.builderEvidenceHash) {
    throw new TypeError("V3 builder evidence crossed its exact plan/source lineage");
  }
  sha256(value.evidenceHash, "V3 builder evidence hash");
  const { evidenceHash: _evidenceHash, ...core } = value;
  if (value.evidenceHash !== canonicalSha256(
    "programmable.router-v2-builder-evidence-commitment.v3", core,
  )) throw new TypeError("V3 builder evidence hash drifted");
}

export function assertReviewerAuthorityAttestationV3(
  descriptor: Readonly<LaunchProfileDescriptorV3>,
  plan: Readonly<ApplicantLaunchPlanV3>,
  evidence: Readonly<BuilderEvidenceCommitmentV3>,
  raw: unknown,
): asserts raw is ReviewerAuthorityAttestationV3 {
  assertBuilderEvidenceCommitmentV3(descriptor, plan, evidence);
  const value = plainRecord(raw, "V3 reviewer authority attestation");
  exactKeys(value, [
    "schemaVersion", "attestationVersion", "decision", "legacyAttestation",
    "legacyAttestationHash", "profileDescriptorHash", "planHash", "builderEvidenceHash",
    "contractArtifactBindingHash", "contractPlanHash", "contractApplicantIdHash",
    "contractBuilderEvidenceHash", "contractReviewerAttestationHash",
    "securityControlHeadHash", "securityEpoch", "securityEpochHash", "policyHash",
    "policyEpoch", "policyEpochHash", "reviewControl", "durableForExactRevision",
    "issuedAt", "attestationHash",
  ], "V3 reviewer authority attestation");
  if (value.schemaVersion !== "programmable.router-v2-reviewer-authority-attestation.v3"
    || value.attestationVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3
    || (value.decision !== "APPROVED" && value.decision !== "DENIED")
    || value.durableForExactRevision !== true) {
    throw new TypeError("V3 reviewer authority attestation version or decision drifted");
  }
  const legacy = assertReviewerAuthorityAttestationV2(
    descriptor.legacyDescriptor,
    ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2,
    plan.legacyPlan,
    evidence.legacyEvidence,
    value.legacyAttestation as ReviewerAuthorityAttestationV2,
  );
  if (value.legacyAttestationHash !== legacy.attestationHash) {
    throw new TypeError("V3 reviewer attestation crossed its archival V2 identity");
  }
  const source = plan.sourceReferents;
  const review = plainRecord(value.reviewControl, "V3 reviewer review control");
  exactKeys(review, ["reviewGenerationHash", "reviewGeneration"],
    "V3 reviewer review control");
  bytes32(review.reviewGenerationHash, "V3 reviewer generation hash");
  uintWordV3(String(review.reviewGeneration), 64, "V3 reviewer generation");
  uintWordV3(String(value.securityEpoch), 64, "V3 reviewer security epoch");
  uintWordV3(String(value.policyEpoch), 64, "V3 reviewer policy epoch");
  for (const key of [
    "contractApplicantIdHash", "contractBuilderEvidenceHash",
    "contractReviewerAttestationHash", "securityControlHeadHash", "securityEpochHash",
    "policyHash", "policyEpochHash",
  ]) bytes32(value[key], `V3 reviewer ${key}`);
  if (value.profileDescriptorHash !== descriptor.descriptorHash
    || value.planHash !== plan.planHash || value.builderEvidenceHash !== evidence.evidenceHash
    || value.contractArtifactBindingHash !== plan.contractArtifactBindingHash
    || value.contractPlanHash !== plan.contractPlanHash
    || value.contractApplicantIdHash !== source.applicantRequest.applicantIdHash
    || value.contractBuilderEvidenceHash !== evidence.contractBuilderEvidenceHash
    || value.contractReviewerAttestationHash
      !== source.applicantRequest.reviewerAttestationHash
    || value.policyHash !== plan.contractPlan.policyHash) {
    throw new TypeError("V3 reviewer attestation crossed plan, evidence or applicant identity");
  }
  sha256(value.attestationHash, "V3 reviewer attestation hash");
  const { attestationHash: _attestationHash, ...core } = value;
  if (value.attestationHash !== canonicalSha256(
    "programmable.router-v2-reviewer-authority-attestation.v3", core,
  )) throw new TypeError("V3 reviewer authority attestation hash drifted");
}

export function assertLaunchIdentitySetV3(raw: unknown): asserts raw is LaunchIdentitySetV3 {
  const value = plainRecord(raw, "Launch identity set");
  exactKeys(value, ["sourceLaunchId", "stampLaunchId", "antiReplayNonce"],
    "Launch identity set");
  const identities = [value.sourceLaunchId, value.stampLaunchId, value.antiReplayNonce];
  for (const identity of identities) bytes32(identity, "Launch identity");
  if (new Set(identities).size !== identities.length) {
    throw new TypeError("sourceLaunchId, stampLaunchId and antiReplayNonce must be distinct");
  }
}

