export function createSha256ToEvmBytes32BindingV1(
  artifactSha256: Sha256Digest,
): Readonly<Sha256ToEvmBytes32BindingV1> {
  const digest = sha256(artifactSha256, "SHA-256 to EVM binding artifact");
  const core = {
    schemaVersion: "programmable.sha256-to-evm-bytes32-binding.v1",
    artifactSha256: digest,
    evmBytes32: `0x${digest.slice("sha256:".length)}` as EvmBytes32V1,
    conversion: "PREFIX_REPLACEMENT_ONLY_NO_REHASH",
  } as const;
  return deepFreeze({ ...core, bindingHash: canonicalSha256(
    "programmable.sha256-to-evm-bytes32-binding.v1", core,
  ) });
}

export function assertSha256ToEvmBytes32BindingV1(
  raw: unknown,
): asserts raw is Sha256ToEvmBytes32BindingV1 {
  const value = plainRecord(raw, "SHA-256 to EVM bytes32 binding");
  exactKeys(value, [
    "schemaVersion", "artifactSha256", "evmBytes32", "conversion", "bindingHash",
  ], "SHA-256 to EVM bytes32 binding");
  if (value.schemaVersion !== "programmable.sha256-to-evm-bytes32-binding.v1"
    || value.conversion !== "PREFIX_REPLACEMENT_ONLY_NO_REHASH") {
    throw new TypeError("SHA-256 to EVM bytes32 binding conversion drifted");
  }
  const digest = sha256(value.artifactSha256, "SHA-256 to EVM binding artifact");
  bytes32WordV3(value.evmBytes32, "SHA-256 to EVM bytes32 value");
  if (value.evmBytes32 !== `0x${digest.slice("sha256:".length)}`) {
    throw new TypeError("SHA-256 to EVM binding must replace only the digest prefix");
  }
  sha256(value.bindingHash, "SHA-256 to EVM binding hash");
  const { bindingHash: _bindingHash, ...core } = value;
  if (value.bindingHash !== canonicalSha256(
    "programmable.sha256-to-evm-bytes32-binding.v1", core,
  )) throw new TypeError("SHA-256 to EVM bytes32 binding hash drifted");
}

export function createCompletedGraphLaunchGrantDigestBindingV1(input: Readonly<{
  readonly contractGrant: Readonly<CompletedGraphLaunchGrantContractV1>;
  readonly contractArtifactBindingHash: Sha256Digest;
  readonly authorityGrantArtifactHash: Sha256Digest;
}>): Readonly<CompletedGraphLaunchGrantDigestBindingV1> {
  assertCompletedGraphLaunchGrantContractV1(input.contractGrant);
  if (input.contractArtifactBindingHash
      !== PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1.artifactBindingHash) {
    throw new TypeError("LaunchGrant digest binding does not name the frozen Contract artifact");
  }
  const exactContractArtifactBinding = createSha256ToEvmBytes32BindingV1(
    input.contractArtifactBindingHash,
  );
  if (input.contractGrant.exactContractBindingHash
      !== exactContractArtifactBinding.evmBytes32) {
    throw new TypeError("Contract LaunchGrant exactContractBindingHash is not the frozen artifact");
  }
  sha256(input.authorityGrantArtifactHash, "Authority grant artifact hash");
  const hashes = computeCompletedGraphLaunchGrantHashPartsV3(input.contractGrant);
  const stampLaunchId = computeCompletedGraphStampLaunchIdV3({
    chainId: input.contractGrant.chainId,
    registry: input.contractGrant.registry,
    launchWallet: input.contractGrant.launchWallet,
    profileKey: input.contractGrant.profileKey,
    contractPlanHash: input.contractGrant.contractPlanHash,
    sourceLaunchId: input.contractGrant.sourceLaunchId,
  });
  const core = {
    schemaVersion: "programmable.router-v2-completed-graph-launch-grant-digest-binding.v1",
    contractGrant: input.contractGrant,
    contractGrantStructHash: hashes.contractGrantStructHash,
    contractGrantDigest: computeCompletedGraphLaunchGrantDigestV3(input.contractGrant),
    stampLaunchId,
    winnerKeyHash: input.contractGrant.winnerKeyHash,
    eip712DomainSeparator: computeCompletedGraphEip712DomainSeparatorV3(
      input.contractGrant.chainId, input.contractGrant.registry,
    ),
    contractGrantAbiSha256: COMPLETED_GRAPH_LAUNCH_GRANT_CONTRACT_ABI_SHA256_V1,
    exactContractArtifactBinding,
    authorityGrantArtifactHash: input.authorityGrantArtifactHash,
  } as const;
  return deepFreeze({ ...core, bindingHash: canonicalSha256(
    "programmable.router-v2-completed-graph-launch-grant-digest-binding.v1", core,
  ) });
}

export function assertCompletedGraphLaunchGrantDigestBindingV1(
  raw: unknown,
): asserts raw is CompletedGraphLaunchGrantDigestBindingV1 {
  const value = plainRecord(raw, "Completed Graph LaunchGrant digest binding");
  exactKeys(value, [
    "schemaVersion", "contractGrant", "contractGrantStructHash", "contractGrantDigest",
    "stampLaunchId", "winnerKeyHash", "eip712DomainSeparator", "contractGrantAbiSha256",
    "exactContractArtifactBinding", "authorityGrantArtifactHash", "bindingHash",
  ], "Completed Graph LaunchGrant digest binding");
  if (value.schemaVersion
      !== "programmable.router-v2-completed-graph-launch-grant-digest-binding.v1") {
    throw new TypeError("Completed Graph LaunchGrant digest binding version drifted");
  }
  const exactArtifact = value.exactContractArtifactBinding as Sha256ToEvmBytes32BindingV1;
  assertSha256ToEvmBytes32BindingV1(exactArtifact);
  const expected = createCompletedGraphLaunchGrantDigestBindingV1({
    contractGrant: value.contractGrant as CompletedGraphLaunchGrantContractV1,
    contractArtifactBindingHash: exactArtifact.artifactSha256,
    authorityGrantArtifactHash: value.authorityGrantArtifactHash as Sha256Digest,
  });
  if (canonicalSha256(
    "programmable.router-v2-completed-graph-launch-grant-digest-binding-equality.v1", value,
  ) !== canonicalSha256(
    "programmable.router-v2-completed-graph-launch-grant-digest-binding-equality.v1", expected,
  )) throw new TypeError("Completed Graph LaunchGrant derived digest binding drifted");
}

export function createLaunchGrantV3(input: Readonly<{
  readonly descriptor: Readonly<LaunchProfileDescriptorV3>;
  readonly plan: Readonly<ApplicantLaunchPlanV3>;
  readonly builderEvidence: Readonly<BuilderEvidenceCommitmentV3>;
  readonly reviewerAttestation: Readonly<ReviewerAuthorityAttestationV3>;
  readonly contractGrantBinding: Readonly<CompletedGraphLaunchGrantDigestBindingV1>;
  readonly authorityGrantArtifactHash: Sha256Digest;
  readonly issuedAt: string;
}>): never {
  assertLaunchProfileDescriptorV3(input.descriptor);
  const descriptor = input.descriptor;
  assertApplicantLaunchPlanV3(descriptor, input.plan);
  assertBuilderEvidenceCommitmentV3(descriptor, input.plan, input.builderEvidence);
  assertReviewerAuthorityAttestationV3(
    descriptor, input.plan, input.builderEvidence, input.reviewerAttestation,
  );
  throw new TypeError(
    "V3.0.0 cannot issue LaunchGrant artifacts; an immutable deployment/profile-bound successor is required",
  );
}

