export function createCompletedGraphAuthenticatedNonUseEvidenceV3(input: Readonly<{
  readonly previousClaim: Readonly<CompletedGraphWinnerReservationClaimV3>;
  readonly checkedAtEpochSeconds: string;
  readonly primaryProviderEvidenceSha256: Sha256Digest;
  readonly secondaryProviderEvidenceSha256: Sha256Digest;
  readonly providerIndependenceEvidenceSha256: Sha256Digest;
  readonly currentnessNonceUnused: true;
  readonly noSubmissionTransaction: true;
  readonly noCanonicalReceipt: true;
  readonly finalizedThroughBlock: string;
}>): Readonly<CompletedGraphAuthenticatedNonUseEvidenceV3> {
  assertCompletedGraphWinnerReservationClaimV3(input.previousClaim);
  const checkedAt = uintValueV3(input.checkedAtEpochSeconds, 64,
    "authenticated non-use checkedAt");
  const expiresAt = uintValueV3(input.previousClaim.reservationExpiresAtEpochSeconds, 64,
    "predecessor reservation expiry");
  if (checkedAt <= expiresAt) {
    throw new TypeError("Authenticated non-use must be checked after predecessor expiry");
  }
  for (const [label, digest] of [
    ["primary provider evidence", input.primaryProviderEvidenceSha256],
    ["secondary provider evidence", input.secondaryProviderEvidenceSha256],
    ["provider independence evidence", input.providerIndependenceEvidenceSha256],
  ] as const) sha256(digest, label);
  if (input.primaryProviderEvidenceSha256 === input.secondaryProviderEvidenceSha256) {
    throw new TypeError("Authenticated non-use requires independent provider evidence");
  }
  if (input.currentnessNonceUnused !== true || input.noSubmissionTransaction !== true
    || input.noCanonicalReceipt !== true) {
    throw new TypeError("Authenticated non-use must prove nonce, transaction and receipt absence");
  }
  uintWordV3(input.finalizedThroughBlock, 64, "authenticated non-use finality block");
  const core = {
    schemaVersion:
      "programmable.router-v2-completed-graph-authenticated-non-use-evidence.v3",
    predecessorClaimHash: input.previousClaim.claimHash,
    contractGrantDigest: input.previousClaim.contractGrantDigest,
    authorityReservationKeySha256: input.previousClaim.authorityReservationKeySha256,
    checkedAtEpochSeconds: input.checkedAtEpochSeconds,
    primaryProviderEvidenceSha256: input.primaryProviderEvidenceSha256,
    secondaryProviderEvidenceSha256: input.secondaryProviderEvidenceSha256,
    providerIndependenceEvidenceSha256: input.providerIndependenceEvidenceSha256,
    currentnessNonceUnused: true,
    noSubmissionTransaction: true,
    noCanonicalReceipt: true,
    finalizedThroughBlock: input.finalizedThroughBlock,
  } as const;
  return deepFreeze({ ...core, evidenceHash: canonicalSha256(
    "programmable.router-v2-completed-graph-authenticated-non-use-evidence.v3", core,
  ) });
}

export function authorizeCompletedGraphReservationSuccessorV3(input: Readonly<{
  readonly grant: Readonly<CompletedGraphLaunchGrantContractV1>;
  readonly previousClaim: Readonly<CompletedGraphWinnerReservationClaimV3>;
  readonly evidence: Readonly<CompletedGraphAuthenticatedNonUseEvidenceV3>;
  readonly observation: Readonly<CompletedGraphGrantCurrentnessObservationV3>;
  readonly trustedNowEpochSeconds: string;
}>): Readonly<CompletedGraphReservationSuccessorAuthorizationV3> {
  assertCompletedGraphLaunchGrantContractV1(input.grant);
  assertCompletedGraphWinnerReservationClaimV3(input.previousClaim);
  assertCompletedGraphAuthenticatedNonUseEvidenceV3(input.evidence);
  const grantDigest = computeCompletedGraphLaunchGrantDigestV3(input.grant);
  if (input.previousClaim.contractGrantDigest !== grantDigest
    || input.previousClaim.contractWinnerKeyHash !== input.grant.winnerKeyHash
    || input.evidence.predecessorClaimHash !== input.previousClaim.claimHash
    || input.evidence.contractGrantDigest !== grantDigest
    || input.evidence.authorityReservationKeySha256
      !== input.previousClaim.authorityReservationKeySha256) {
    throw new TypeError("Reservation successor crossed its predecessor or Contract grant");
  }
  const trustedNow = uintValueV3(input.trustedNowEpochSeconds, 64,
    "reservation successor trusted time");
  const expiresAt = BigInt(input.previousClaim.reservationExpiresAtEpochSeconds);
  const checkedAt = BigInt(input.evidence.checkedAtEpochSeconds);
  if (trustedNow <= expiresAt || trustedNow < checkedAt) {
    throw new TypeError("Reservation successor requires expired predecessor and fresh non-use");
  }
  const currentness = evaluateCompletedGraphGrantCurrentnessV3({
    grant: input.grant,
    observation: input.observation,
  });
  if (!currentness.mayIssueCurrentness) {
    throw new TypeError(`Reservation successor requires current Active grant: ${currentness.state}`);
  }
  const predecessorGeneration = uintValueV3(input.previousClaim.reservationGeneration, 64,
    "predecessor reservation generation");
  const nextGeneration = predecessorGeneration + 1n;
  if (nextGeneration >= 1n << 64n) {
    throw new TypeError("Reservation successor generation exceeds uint64");
  }
  const core = {
    schemaVersion:
      "programmable.router-v2-completed-graph-reservation-successor-authorization.v3",
    predecessorClaimHash: input.previousClaim.claimHash,
    predecessorReservationGeneration: input.previousClaim.reservationGeneration,
    nextReservationGeneration: nextGeneration.toString(10),
    nonUseEvidenceHash: input.evidence.evidenceHash,
    contractGrantDigest: grantDigest,
    authorityReservationKeySha256: input.previousClaim.authorityReservationKeySha256,
    trustedNowEpochSeconds: input.trustedNowEpochSeconds,
  } as const;
  return deepFreeze({ ...core, authorizationHash: canonicalSha256(
    "programmable.router-v2-completed-graph-reservation-successor-authorization.v3", core,
  ) });
}

