export function createLaunchProfileDescriptorV3(input: Readonly<{
  legacyDescriptor: Readonly<LaunchProfileDescriptorV2>;
  contractArtifactBinding: Readonly<CompletedGraphAdoptionContractArtifactBindingV1> | null;
  contractDeploymentBinding: Readonly<CompletedGraphAdoptionContractDeploymentBindingV1> | null;
  profileCapabilityBinding: Readonly<CompletedGraphAdoptionProfileCapabilityBindingV1> | null;
  blockers: readonly string[];
}>): Readonly<LaunchProfileDescriptorV3> {
  const legacyDescriptor = assertLaunchProfileDescriptorV2(input.legacyDescriptor);
  const frozenLegacy = ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2.descriptors.find(
    ({ slotId }) => slotId === legacyDescriptor.slotId,
  );
  if (frozenLegacy?.descriptorHash !== legacyDescriptor.descriptorHash) {
    throw new TypeError("V3 descriptor legacy profile is outside the frozen V2 catalog");
  }
  const artifactPresent = input.contractArtifactBinding !== null;
  const executable = artifactPresent && input.contractDeploymentBinding !== null
    && input.profileCapabilityBinding !== null;
  if (input.legacyDescriptor.architecture !== "COMPLETED_GRAPH_ADOPTION"
    && (artifactPresent || input.contractDeploymentBinding !== null
      || input.profileCapabilityBinding !== null)) {
    throw new TypeError("Only COMPLETED_GRAPH_ADOPTION may consume this exact ADOPT artifact");
  }
  if (executable) {
    throw new TypeError(
      "V3.0.0 activation is disabled; exact deployment requires a separately frozen successor",
    );
  }
  if ((input.contractDeploymentBinding === null) !== (input.profileCapabilityBinding === null)) {
    throw new TypeError("Deployment and profile capability bindings must enter together");
  }
  const state: LaunchProfileStateV3 = artifactPresent
    ? "DENY_PENDING_DEPLOYMENT_AND_PROFILE_BINDING"
    : "DENY_PENDING_CONTRACT_ARTIFACT";
  const core = {
    schemaVersion: "programmable.router-v2-launch-profile-descriptor.v3",
    descriptorVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3,
    slotId: input.legacyDescriptor.slotId,
    architecture: input.legacyDescriptor.architecture,
    state,
    activationAllowed: false,
    sourceScheduleRequirement: input.legacyDescriptor.sourceScheduleRequirement,
    legacyDescriptor: input.legacyDescriptor,
    legacyDescriptorHash: input.legacyDescriptor.descriptorHash,
    contractArtifactBinding: input.contractArtifactBinding,
    contractArtifactBindingHash: input.contractArtifactBinding?.artifactBindingHash ?? null,
    contractDeploymentBinding: input.contractDeploymentBinding,
    profileCapabilityBinding: input.profileCapabilityBinding,
    blockers: [...input.blockers],
  } as const;
  const result = deepFreeze({ ...core, descriptorHash: canonicalSha256(
    "programmable.router-v2-launch-profile-descriptor.v3", core,
  ) });
  assertLaunchProfileDescriptorV3(result);
  return result;
}

export function assertLaunchProfileDescriptorV3(
  raw: unknown,
): asserts raw is LaunchProfileDescriptorV3 {
  const value = plainRecord(raw, "V3 launch profile descriptor");
  exactKeys(value, [
    "schemaVersion", "descriptorVersion", "slotId", "architecture", "state",
    "activationAllowed", "sourceScheduleRequirement", "legacyDescriptor",
    "legacyDescriptorHash", "contractArtifactBinding", "contractArtifactBindingHash",
    "contractDeploymentBinding", "profileCapabilityBinding", "blockers", "descriptorHash",
  ], "V3 launch profile descriptor");
  if (value.schemaVersion !== "programmable.router-v2-launch-profile-descriptor.v3"
    || value.descriptorVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3) {
    throw new TypeError("V3 launch profile descriptor version drifted");
  }
  const legacy = assertLaunchProfileDescriptorV2(
    value.legacyDescriptor as LaunchProfileDescriptorV2,
  );
  const frozenLegacy = ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2.descriptors.find(
    ({ slotId }) => slotId === legacy.slotId,
  );
  if (frozenLegacy?.descriptorHash !== legacy.descriptorHash
    || value.slotId !== legacy.slotId || value.architecture !== legacy.architecture
    || value.legacyDescriptorHash !== legacy.descriptorHash
    || value.sourceScheduleRequirement !== legacy.sourceScheduleRequirement) {
    throw new TypeError("V3 descriptor crossed its frozen V2 profile identity");
  }
  const blockers = value.blockers;
  if (!Array.isArray(blockers) || blockers.length === 0 || blockers.length > 16
    || blockers.some((entry) => typeof entry !== "string" || entry.length === 0)
    || new Set(blockers).size !== blockers.length) {
    throw new TypeError("V3 DENY descriptor requires a unique nonempty blocker set");
  }
  const completed = legacy.architecture === "COMPLETED_GRAPH_ADOPTION";
  if (completed) {
    assertCompletedGraphAdoptionContractArtifactBindingV1(value.contractArtifactBinding);
    if (value.contractArtifactBindingHash
        !== PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1.artifactBindingHash
      || value.contractDeploymentBinding !== null || value.profileCapabilityBinding !== null
      || value.state !== "DENY_PENDING_DEPLOYMENT_AND_PROFILE_BINDING"
      || value.activationAllowed !== false) {
      throw new TypeError("V3.0.0 completed-graph descriptor is not frozen UNDEPLOYED/DENY");
    }
  } else if (value.contractArtifactBinding !== null
    || value.contractArtifactBindingHash !== null || value.contractDeploymentBinding !== null
    || value.profileCapabilityBinding !== null || value.state !== "DENY_PENDING_CONTRACT_ARTIFACT"
    || value.activationAllowed !== false) {
    throw new TypeError("V3.0.0 unsupported profile slot must remain NULL_DENY");
  }
  sha256(value.descriptorHash, "V3 descriptor hash");
  const { descriptorHash: _descriptorHash, ...core } = value;
  if (value.descriptorHash !== canonicalSha256(
    "programmable.router-v2-launch-profile-descriptor.v3", core,
  )) throw new TypeError("V3 launch profile descriptor hash drifted");
}

export function createLaunchProfileCatalogV3(
  descriptors: readonly Readonly<LaunchProfileDescriptorV3>[],
): Readonly<LaunchProfileCatalogV3> {
  for (const descriptor of descriptors) assertLaunchProfileDescriptorV3(descriptor);
  const frozenSlots = new Set(ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2.descriptors
    .map(({ slotId }) => slotId));
  if (descriptors.length !== 6 || new Set(descriptors.map(({ slotId }) => slotId)).size !== 6
    || descriptors.some(({ slotId }) => !frozenSlots.has(slotId))) {
    throw new TypeError("V3 target catalog must contain exactly six distinct profile slots");
  }
  const ordered = [...descriptors].sort((left, right) => compare(left.slotId, right.slotId));
  const core = {
    schemaVersion: "programmable.router-v2-launch-profile-catalog.v3",
    catalogVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3,
    descriptors: ordered,
  } as const;
  const result = deepFreeze({ ...core, catalogHash: canonicalSha256(
    "programmable.router-v2-launch-profile-catalog.v3", core,
  ) });
  assertLaunchProfileCatalogV3(result);
  return result;
}

export function assertLaunchProfileCatalogV3(
  raw: unknown,
): asserts raw is LaunchProfileCatalogV3 {
  const value = plainRecord(raw, "V3 launch profile catalog");
  exactKeys(value, ["schemaVersion", "catalogVersion", "descriptors", "catalogHash"],
    "V3 launch profile catalog");
  if (value.schemaVersion !== "programmable.router-v2-launch-profile-catalog.v3"
    || value.catalogVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V3
    || !Array.isArray(value.descriptors) || value.descriptors.length !== 6) {
    throw new TypeError("V3 launch profile catalog version or cardinality drifted");
  }
  for (const descriptor of value.descriptors) assertLaunchProfileDescriptorV3(descriptor);
  const slots = value.descriptors.map(({ slotId }) => slotId);
  if (new Set(slots).size !== 6
    || slots.some((slotId) => !ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2.descriptors
      .some((legacy) => legacy.slotId === slotId))) {
    throw new TypeError("V3 launch profile catalog slot identity drifted");
  }
  const ordered = [...value.descriptors].sort((left, right) => compare(left.slotId, right.slotId));
  if (value.descriptors.some((entry, index) => entry.descriptorHash !== ordered[index]?.descriptorHash)) {
    throw new TypeError("V3 launch profile catalog is not canonically ordered");
  }
  sha256(value.catalogHash, "V3 catalog hash");
  const { catalogHash: _catalogHash, ...core } = value;
  if (value.catalogHash !== canonicalSha256(
    "programmable.router-v2-launch-profile-catalog.v3", core,
  )) throw new TypeError("V3 launch profile catalog hash drifted");
}

export const ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V3 = createLaunchProfileCatalogV3(
  ROUTER_V2_SHARED_TARGET_PROFILE_CATALOG_V2.descriptors.map((legacyDescriptor) => {
    const completed = legacyDescriptor.architecture === "COMPLETED_GRAPH_ADOPTION";
    return createLaunchProfileDescriptorV3({
      legacyDescriptor,
      contractArtifactBinding: completed
        ? PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1 : null,
      contractDeploymentBinding: null,
      profileCapabilityBinding: null,
      blockers: completed
        ? [
          "Exact Contract deployment, source verification and finality receipts are absent.",
          "Validator, Preflight and Registry live codehashes require constructor-immutable specialization receipts.",
          "Profile capability registration and Authority runtime binding are absent.",
          "Production activation remains DENY.",
        ]
        : ["No independently-passed immutable Contract artifact is bound for this profile slot."],
    });
  }),
);

