function computeGitObjectCommitmentV3(
  typehash: EvmBytes32V1,
  gitObjectId: GitObjectIdBytes20V3,
  label: string,
): EvmBytes32V1 {
  if (!/^0x[0-9a-f]{40}$/u.test(gitObjectId)
    || gitObjectId === "0x0000000000000000000000000000000000000000") {
    throw new TypeError(`${label} Git object id must be nonzero exact raw lowercase bytes20`);
  }
  const encoded = concatBytes(
    hexBytes(typehash, `${label} typehash`),
    rightPad32(hexBytes(gitObjectId, `${label} Git object id`)),
  );
  return keccak256V1(encoded) as EvmBytes32V1;
}

function gitObjectId(raw: unknown, label: string): GitObjectIdBytes20V3 {
  if (typeof raw !== "string" || !/^0x[0-9a-f]{40}$/u.test(raw)
    || raw === "0x0000000000000000000000000000000000000000") {
    throw new TypeError(`${label} must be nonzero exact raw lowercase bytes20`);
  }
  return raw as GitObjectIdBytes20V3;
}

function gitObjectWordV3(raw: unknown, label: string): Uint8Array {
  return rightPad32(hexBytes(gitObjectId(raw, label), label));
}

function rightPad32(value: Uint8Array): Uint8Array {
  if (value.byteLength > 32) throw new TypeError("ABI static bytes value exceeds one word");
  const output = new Uint8Array(32);
  output.set(value);
  return output;
}

function typehash(
  key: keyof typeof PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1.typehashes,
): Uint8Array {
  const value = PROGRAMMABLE_COMPLETED_GRAPH_ADOPTION_CONTRACT_CANDIDATE_V1.typehashes[key];
  if (value === undefined) throw new TypeError(`Unknown Contract typehash ${String(key)}`);
  return bytes32WordV3(value, `Contract typehash ${String(key)}`);
}

function keccakWordsV3(words: readonly Uint8Array[]): EvmBytes32V1 {
  if (words.some((word) => word.byteLength !== 32)) {
    throw new TypeError("ABI word preimage contains a non-word value");
  }
  return keccak256V1(concatBytes(...words)) as EvmBytes32V1;
}

function bytes32WordV3(raw: unknown, label: string): Uint8Array {
  if (typeof raw !== "string" || !/^0x[0-9a-f]{64}$/u.test(raw)) {
    throw new TypeError(`${label} must be lowercase bytes32`);
  }
  return hexBytes(raw, label);
}

function addressWordV3(raw: unknown, label: string): Uint8Array {
  if (typeof raw !== "string" || !/^0x[0-9a-f]{40}$/u.test(raw)
    || raw === `0x${"0".repeat(40)}`) {
    throw new TypeError(`${label} must be a nonzero lowercase EVM address`);
  }
  const output = new Uint8Array(32);
  output.set(hexBytes(raw, label), 12);
  return output;
}

function addressWordAllowZeroV3(raw: unknown, label: string): Uint8Array {
  if (typeof raw !== "string" || !/^0x[0-9a-f]{40}$/u.test(raw)) {
    throw new TypeError(`${label} must be a lowercase EVM address`);
  }
  const output = new Uint8Array(32);
  output.set(hexBytes(raw, label), 12);
  return output;
}

function boolWordV3(raw: unknown, label: string): Uint8Array {
  if (typeof raw !== "boolean") throw new TypeError(`${label} must be boolean`);
  return uintWordV3(raw ? "1" : "0", 8, label);
}

function uintWordV3(raw: string, bits: 8 | 16 | 64 | 256, label: string): Uint8Array {
  const value = uintValueV3(raw, bits, label);
  const hex = value.toString(16).padStart(64, "0");
  return Uint8Array.from(Buffer.from(hex, "hex"));
}

function uintValueV3(raw: string, bits: 8 | 16 | 64 | 256, label: string): bigint {
  if (!/^(?:0|[1-9][0-9]*)$/u.test(raw)) throw new TypeError(`${label} is not canonical uint`);
  const value = BigInt(raw);
  if (value >= 1n << BigInt(bits)) throw new TypeError(`${label} exceeds uint${bits}`);
  return value;
}

function hexBytes(raw: string, label: string): Uint8Array {
  if (!/^0x(?:[0-9a-f]{2})+$/u.test(raw)) throw new TypeError(`${label} must be lowercase hex`);
  return Uint8Array.from(Buffer.from(raw.slice(2), "hex"));
}

function concatBytes(...parts: readonly Uint8Array[]): Uint8Array {
  const output = new Uint8Array(parts.reduce((sum, part) => sum + part.byteLength, 0));
  let offset = 0;
  for (const part of parts) {
    output.set(part, offset);
    offset += part.byteLength;
  }
  return output;
}

function bytes32(raw: unknown, label: string): EvmBytes32V1 {
  if (typeof raw !== "string" || !/^0x[0-9a-f]{64}$/u.test(raw)
    || raw === `0x${"0".repeat(64)}`) throw new TypeError(`${label} must be nonzero bytes32`);
  return raw as EvmBytes32V1;
}

function sha256(raw: unknown, label: string): Sha256Digest {
  if (typeof raw !== "string" || !/^sha256:[0-9a-f]{64}$/u.test(raw)) {
    throw new TypeError(`${label} must be a canonical lowercase SHA-256 digest`);
  }
  return raw as Sha256Digest;
}

