/** A pinned HSM/KMS or Safe/ERC-1271 adapter, never a generic signing-byte port. */
export interface LaunchGrantSignerPortV2 {
  /**
   * The provider must implement a create-or-return-identical operation keyed
   * by signerRequestHash/idempotencyKeyHash. Repeating this call after a
   * process crash can never create a second signature or successor permit.
   */
  signAfterVerifiedWinnerReservation(input: Readonly<{
    idempotencyMode: "ISSUE_OR_RETURN_IDENTICAL_SIGNATURE";
    signerRequestHash: Sha256Digest;
    grantDigest: EvmBytes32V1;
    transportRequestHash: Sha256Digest;
    winnerReservationHash: Sha256Digest;
    winnerReservationCoreHash: Sha256Digest;
    idempotencyKeyHash: Sha256Digest;
    signerAuthorityBindingHash: Sha256Digest;
    signerKeyEpoch: string;
    validAfterEpochSeconds: string;
    deadlineEpochSeconds: string;
    currentnessHash: Sha256Digest;
  }>): Promise<Readonly<
    | ({ outcome: "SIGNED" } & SignedLaunchGrantTransportV2)
    | { outcome: "AMBIGUOUS_PARKED" | "PROVIDER_OUTAGE_PARKED"; retryNotBeforeEpochSeconds: string }
  >>;
  reconcileByTransportRequestHash(input: Readonly<{
    signerRequestHash: Sha256Digest;
    transportRequestHash: Sha256Digest;
    idempotencyKeyHash: Sha256Digest;
    signerAuthorityBindingHash: Sha256Digest;
    signerKeyEpoch: string;
  }>): Promise<Readonly<
    | ({ outcome: "SIGNED" } & SignedLaunchGrantTransportV2)
    | { outcome: "NOT_FOUND_NO_RESIGN" | "STILL_AMBIGUOUS_PARKED"; retryNotBeforeEpochSeconds?: string }
  >>;
  assertIssuedExecutionPermit(input: Readonly<{
    signerRequestHash: Sha256Digest;
    signatureArtifactSha256: Sha256Digest;
    signerAttestationSha256: Sha256Digest;
    grantDigest: EvmBytes32V1;
    transportRequestHash: Sha256Digest;
    winnerReservationHash: Sha256Digest;
    winnerReservationCoreHash: Sha256Digest;
    idempotencyKeyHash: Sha256Digest;
    signerAuthorityBindingHash: Sha256Digest;
    signerKeyEpoch: string;
  }>): void;
}

