export function createLaunchGrantContractBindingV2(
  raw: Omit<LaunchGrantContractBindingV2, "bindingHash">,
): Readonly<LaunchGrantContractBindingV2> {
  exactKeys(raw, [
    "chainId", "grantAbiArtifactSha256", "grantCompilerArtifactSha256",
    "grantConsumerSelector", "grantRegistry", "grantRegistryRuntimeCodeHash", "grantReleaseHash",
    "grantStateReaderSelector", "grantTypehash", "grantVerifierArtifactSha256",
    "revenueBindingHash", "router", "routerRuntimeCodeHash",
  ], "launch grant contract binding");
  const core = {
    chainId: positiveDecimal(raw.chainId, "grant chain id"),
    router: nonzeroAddress(raw.router, "grant router"),
    routerRuntimeCodeHash: nonzeroBytes32(raw.routerRuntimeCodeHash, "grant router runtime"),
    grantRegistry: nonzeroAddress(raw.grantRegistry, "grant registry"),
    grantRegistryRuntimeCodeHash: nonzeroBytes32(
      raw.grantRegistryRuntimeCodeHash,
      "grant registry runtime",
    ),
    grantTypehash: nonzeroBytes32(raw.grantTypehash, "grant typehash"),
    grantStateReaderSelector: bytes4(raw.grantStateReaderSelector, "grant state selector"),
    grantConsumerSelector: bytes4(raw.grantConsumerSelector, "grant consumer selector"),
    grantAbiArtifactSha256: sha256(raw.grantAbiArtifactSha256, "grant ABI artifact"),
    grantCompilerArtifactSha256: sha256(
      raw.grantCompilerArtifactSha256,
      "grant compiler artifact",
    ),
    grantVerifierArtifactSha256: sha256(
      raw.grantVerifierArtifactSha256,
      "grant verifier artifact",
    ),
    grantReleaseHash: sha256(raw.grantReleaseHash, "grant release"),
    revenueBindingHash: sha256(raw.revenueBindingHash, "grant revenue binding"),
  };
  return deepFreeze({
    ...core,
    bindingHash: canonicalSha256("programmable.router-v2-launch-grant-contract-binding.v2", core),
  });
}

export function createLaunchProfileDescriptorV2(raw: Readonly<{
  legacyDescriptor: LaunchProfileDescriptorV1;
  launchGrantContractBinding: LaunchGrantContractBindingV2 | null;
  state: LaunchProfileStateV1;
  activationAllowed: boolean;
  sourceScheduleRequirement: SourceScheduleRequirementV2;
  blockers: readonly string[];
}>): Readonly<LaunchProfileDescriptorV2> {
  exactKeys(raw, [
    "activationAllowed", "blockers", "launchGrantContractBinding", "legacyDescriptor", "state",
    "sourceScheduleRequirement",
  ], "launch profile descriptor v2 input");
  const legacyDescriptor = assertLaunchProfileDescriptorV1(raw.legacyDescriptor);
  const binding = raw.launchGrantContractBinding === null
    ? null
    : assertLaunchGrantContractBindingV2(raw.launchGrantContractBinding);
  const blockers = stringSet(raw.blockers, "grant profile blocker");
  if (raw.state === "ENABLED") {
    if (!raw.activationAllowed || binding === null || blockers.length !== 0
      || legacyDescriptor.state !== "ENABLED") {
      throw new TypeError("enabled grant profile lacks exact Contract and legacy profile bindings");
    }
  } else if (raw.activationAllowed) {
    throw new TypeError("disabled grant profile cannot allow activation");
  }
  if (raw.state === "DENY_PENDING_CONTRACT_FREEZE" && binding !== null) {
    throw new TypeError("contract-pending grant profile contains a guessed binding");
  }
  const normalizedSourceScheduleRequirement = sourceScheduleRequirement(
    raw.sourceScheduleRequirement,
  );
  const capabilitySemantics = legacyDescriptor.capabilitySemantics;
  if ((capabilitySemantics === "ADOPT" && normalizedSourceScheduleRequirement !== "FORBIDDEN")
    || (normalizedSourceScheduleRequirement === "REQUIRED" && capabilitySemantics !== "EXECUTE")) {
    throw new TypeError("source schedule requirement crosses its profile capability");
  }
  if (binding !== null && legacyDescriptor.exactContractBinding !== null
    && (binding.chainId !== legacyDescriptor.exactContractBinding.chainId
      || binding.router !== legacyDescriptor.exactContractBinding.router
      || binding.routerRuntimeCodeHash
        !== legacyDescriptor.exactContractBinding.routerRuntimeCodeHash)) {
    throw new TypeError("launch grant binding crosses its exact Router profile");
  }
  const core = {
    schemaVersion: "programmable.router-v2-launch-profile-descriptor.v2" as const,
    descriptorVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2,
    slotId: legacyDescriptor.slotId,
    architecture: legacyDescriptor.architecture,
    state: raw.state,
    activationAllowed: raw.activationAllowed,
    sourceScheduleRequirement: normalizedSourceScheduleRequirement,
    legacyDescriptor,
    legacyDescriptorHash: legacyDescriptor.descriptorHash,
    launchGrantContractBinding: binding,
    grantTypehash: binding?.grantTypehash ?? null,
    grantStateReaderSelector: binding?.grantStateReaderSelector ?? null,
    grantConsumerSelector: binding?.grantConsumerSelector ?? null,
    grantReleaseHash: binding?.grantReleaseHash ?? null,
    revenueBindingHash: binding?.revenueBindingHash ?? null,
    blockers,
  };
  return deepFreeze({ ...core, descriptorHash: canonicalSha256(core.schemaVersion, core) });
}

export function assertLaunchProfileDescriptorV2(
  raw: LaunchProfileDescriptorV2,
): Readonly<LaunchProfileDescriptorV2> {
  plainRecord(raw, "launch profile descriptor v2");
  const {
    architecture: _architecture,
    descriptorHash: _descriptorHash,
    descriptorVersion: _descriptorVersion,
    grantConsumerSelector: _grantConsumerSelector,
    grantReleaseHash: _grantReleaseHash,
    grantStateReaderSelector: _grantStateReaderSelector,
    grantTypehash: _grantTypehash,
    legacyDescriptorHash: _legacyDescriptorHash,
    revenueBindingHash: _revenueBindingHash,
    schemaVersion: _schemaVersion,
    slotId: _slotId,
    ...input
  } = raw;
  return exactArtifact(raw, createLaunchProfileDescriptorV2(input), "launch profile descriptor v2");
}

export function createLaunchProfileCatalogV2(
  descriptorsRaw: readonly LaunchProfileDescriptorV2[],
): Readonly<LaunchProfileCatalogV2> {
  if (!Array.isArray(descriptorsRaw) || descriptorsRaw.length < 1 || descriptorsRaw.length > 64) {
    throw new TypeError("launch grant catalog cardinality is invalid");
  }
  const descriptors = descriptorsRaw.map(assertLaunchProfileDescriptorV2)
    .sort((left, right) => compare(left.slotId, right.slotId));
  unique(descriptors.map(({ slotId }) => slotId), "launch grant profile slots");
  const core = {
    schemaVersion: "programmable.router-v2-launch-profile-catalog.v2" as const,
    catalogVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2,
    descriptors: deepFreeze(descriptors),
  };
  return deepFreeze({ ...core, catalogHash: canonicalSha256(core.schemaVersion, core) });
}

export function createLaunchExecutionTimingV2(
  raw: LaunchExecutionTimingInputV2,
): Readonly<LaunchExecutionTimingV2> {
  exactKeys(raw, ["kind", "scheduleAnchor"], "launch execution timing input");
  if (raw.kind === "NO_SOURCE_SCHEDULE_CONSTRAINT") {
    if (raw.scheduleAnchor !== null) {
      throw new TypeError("evergreen execution timing cannot carry a source schedule anchor");
    }
    const core = {
      kind: "NO_SOURCE_SCHEDULE_CONSTRAINT" as const,
      scheduleAnchor: null,
    };
    return deepFreeze({
      ...core,
      timingHash: canonicalSha256("programmable.router-v2-launch-execution-timing.v2", core),
    });
  }
  if (raw.kind !== "SOURCE_SCHEDULE_ANCHOR" || raw.scheduleAnchor === null) {
    throw new TypeError("launch execution timing kind is invalid");
  }
  exactKeys(raw.scheduleAnchor, [
    "evidenceSha256", "sourceConstraintHash", "validAfterEpochSeconds", "validBeforeEpochSeconds",
  ], "source schedule anchor");
  const validAfterEpochSeconds = decimal(
    raw.scheduleAnchor.validAfterEpochSeconds,
    64,
    "source schedule anchor valid-after",
  );
  const validBeforeEpochSeconds = decimal(
    raw.scheduleAnchor.validBeforeEpochSeconds,
    64,
    "source schedule anchor valid-before",
  );
  if (BigInt(validBeforeEpochSeconds) <= BigInt(validAfterEpochSeconds)
    || BigInt(validBeforeEpochSeconds) - BigInt(validAfterEpochSeconds)
      > BigInt(ROUTER_V2_MAXIMUM_SOURCE_SCHEDULE_ANCHOR_SECONDS_V2)) {
    throw new TypeError("source schedule anchor window is invalid");
  }
  const core = {
    kind: "SOURCE_SCHEDULE_ANCHOR" as const,
    scheduleAnchor: {
      sourceConstraintHash: sha256(
        raw.scheduleAnchor.sourceConstraintHash,
        "source schedule anchor constraint",
      ),
      evidenceSha256: sha256(raw.scheduleAnchor.evidenceSha256, "source schedule anchor evidence"),
      validAfterEpochSeconds,
      validBeforeEpochSeconds,
    },
  };
  return deepFreeze({
    ...core,
    timingHash: canonicalSha256("programmable.router-v2-launch-execution-timing.v2", core),
  });
}

export function assertLaunchExecutionTimingV2(
  capabilitySemantics: "EXECUTE" | "ADOPT",
  requirement: SourceScheduleRequirementV2,
  raw: LaunchExecutionTimingV2,
): Readonly<LaunchExecutionTimingV2> {
  const rebuilt = createLaunchExecutionTimingV2({
    kind: raw.kind,
    scheduleAnchor: raw.scheduleAnchor,
  });
  if (canonicalizeJson(raw) !== canonicalizeJson(rebuilt)) {
    throw new TypeError("launch execution timing drifted from its canonical construction");
  }
  if ((capabilitySemantics === "ADOPT" || requirement === "FORBIDDEN")
    && rebuilt.kind !== "NO_SOURCE_SCHEDULE_CONSTRAINT") {
    throw new TypeError("completed-graph adoption cannot be silently time-bounded as execution");
  }
  if (requirement === "REQUIRED" && rebuilt.kind !== "SOURCE_SCHEDULE_ANCHOR") {
    throw new TypeError("reviewed execution profile requires its exact source schedule anchor");
  }
  return rebuilt;
}

function assertLaunchExecutionTimingCurrentV2(
  capabilitySemantics: "EXECUTE" | "ADOPT",
  requirement: SourceScheduleRequirementV2,
  timing: LaunchExecutionTimingV2,
  nowEpochSeconds: bigint,
): void {
  const canonical = assertLaunchExecutionTimingV2(capabilitySemantics, requirement, timing);
  if (canonical.kind === "SOURCE_SCHEDULE_ANCHOR"
    && (nowEpochSeconds < BigInt(canonical.scheduleAnchor.validAfterEpochSeconds)
      || nowEpochSeconds >= BigInt(canonical.scheduleAnchor.validBeforeEpochSeconds))) {
    throw new TypeError("source schedule anchor is not currently executable");
  }
}

export function createApplicantLaunchPlanV2(
  descriptorRaw: LaunchProfileDescriptorV2,
  legacyPlanRaw: ApplicantLaunchPlanV1,
  executionTimingRaw: LaunchExecutionTimingV2,
  sourceHeadCommitRaw: string,
): Readonly<ApplicantLaunchPlanV2> {
  const descriptor = assertLaunchProfileDescriptorV2(descriptorRaw);
  const legacyPlan = assertApplicantLaunchPlanV1(descriptor.legacyDescriptor, legacyPlanRaw);
  const executionTiming = assertLaunchExecutionTimingV2(
    legacyPlan.capabilitySemantics,
    descriptor.sourceScheduleRequirement,
    executionTimingRaw,
  );
  const componentIdentitiesHash = canonicalSha256(
    "programmable.router-v2-launch-component-identities.v2",
    legacyPlan.componentIdentities,
  );
  const core = {
    schemaVersion: "programmable.router-v2-applicant-launch-plan.v2" as const,
    planVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2,
    profileDescriptorHash: descriptor.descriptorHash,
    legacyPlan,
    legacyPlanHash: legacyPlan.planHash,
    sourceRepository: legacyPlan.sourceRepository,
    sourceCommit: legacyPlan.sourceCommit,
    sourceHeadCommit: gitObject(sourceHeadCommitRaw, "plan source head commit"),
    sourceTree: legacyPlan.sourceTree,
    launchWallet: legacyPlan.launchWallet,
    componentGraphHash: legacyPlan.componentGraphHash,
    componentIdentities: legacyPlan.componentIdentities,
    componentIdentitiesHash,
    expectedRuntimeCodehashSetHash: legacyPlan.exactRuntimeSetHash,
    configurationHash: legacyPlan.configurationHash,
    poolKeyHash: legacyPlan.poolKeyHash,
    poolId: legacyPlan.poolId,
    resultHash: legacyPlan.resultHash,
    launchId: legacyPlan.launchId,
    actionSemanticHash: legacyPlan.compiledActionSemanticHash,
    executionTiming,
    executionTimingHash: executionTiming.timingHash,
    issuedAt: legacyPlan.issuedAt,
  };
  return deepFreeze({ ...core, planHash: canonicalSha256(core.schemaVersion, core) });
}

