export async function consumeLaunchGrantAtomicallyV2(input: Readonly<{
  context: LaunchGrantExecutionContextV2;
  winnerReservationStore: LaunchGrantWinnerReservationStoreV2;
  signer: LaunchGrantSignerPortV2;
  walletIntentVerifier: LaunchGrantWalletIntentVerifierPortV2;
  verifiedWalletIntent: VerifiedLaunchGrantWalletIntentV2;
  winnerReservation: LaunchGrantWinnerReservationClaimV2;
  permit: ExecutionPermitV2;
  transactionHash: EvmBytes32V1;
  idempotencyKeyHash: Sha256Digest;
  consumer: LaunchGrantAtomicConsumerPortV2;
}>): Promise<Readonly<{
  outcome: LaunchGrantAtomicConsumptionOutcomeV2;
  receipt: Readonly<LaunchGrantConsumptionReceiptV2> | null;
  executionProofHash: Sha256Digest;
}>> {
  const context = assertLaunchGrantCurrentControlContextV2(input.context);
  const winnerReservation = assertLaunchGrantWinnerReservationClaimV2(input.winnerReservation);
  assertStoreIssuedReservationV2(
    input.winnerReservationStore,
    context.securityControlHead,
    winnerReservation,
  );
  const permit = assertExecutionPermitV2({
    context: input.context,
    winnerReservationStore: input.winnerReservationStore,
    signer: input.signer,
    walletIntentVerifier: input.walletIntentVerifier,
    verifiedWalletIntent: input.verifiedWalletIntent,
    winnerReservation,
    raw: input.permit,
  });
  const verifiedWalletIntent = assertVerifiedLaunchGrantWalletIntentV2(
    input.context,
    input.walletIntentVerifier,
    input.verifiedWalletIntent,
  );
  const idempotencyKeyHash = sha256(
    input.idempotencyKeyHash,
    "grant consumption idempotency key",
  );
  if (winnerReservation.idempotencyKeyHash !== idempotencyKeyHash
    || permit.grantDigest !== context.grant.grantDigest
    || permit.grantStateHeadHash !== context.stateHead.headHash
    || permit.securityControlHeadHash !== context.securityControlHead.headHash
    || permit.currentnessHash !== context.currentnessHash
    || permit.winnerReservationHash !== winnerReservation.reservationHash) {
    throw new TypeError("atomic LaunchGrant consumption crosses its current one-use permit");
  }
  const transactionHash = nonzeroBytes32(input.transactionHash, "grant consumption transaction");
  const executionProof = createLaunchGrantAtomicExecutionProofV2({
    context,
    permit,
    verifiedWalletIntent,
    reservation: winnerReservation,
    idempotencyKeyHash,
  });
  const result = await input.consumer.consumeActiveGrantAtomically({
    grantDigest: context.grant.grantDigest,
    expectedStateHeadHash: context.stateHead.headHash,
    permitHash: permit.permitHash,
    winnerReservationHash: permit.winnerReservationHash,
    transportRequestHash: permit.transportRequestHash,
    walletIntentHash: permit.walletIntent.intentHash,
    walletIntentVerificationHash: permit.walletIntentVerificationHash,
    actionCommitment: permit.actionCommitment,
    executionTimingHash: context.grant.executionTimingHash,
    currentnessHash: permit.currentnessHash,
    executionProof,
    transactionHash,
    idempotencyKeyHash,
  });
  if (!( ["CONSUMED", "SUSPENDED", "REVOKED", "ALREADY_CONSUMED",
    "LOST_TO_CONCURRENT_WINNER"] as const)
    .includes(result.outcome as "CONSUMED" | "SUSPENDED" | "REVOKED" | "ALREADY_CONSUMED"
      | "LOST_TO_CONCURRENT_WINNER")) {
    throw new TypeError("atomic LaunchGrant consumer returned an invalid outcome");
  }
  if (result.outcome === "CONSUMED") {
    if (result.receipt === null) {
      throw new TypeError("winning atomic LaunchGrant consumption lacks its receipt");
    }
    const receipt = assertLaunchGrantConsumptionReceiptV2(result.receipt);
    if (receipt.grantDigest !== context.grant.grantDigest
      || receipt.previousStateHeadHash !== context.stateHead.headHash
      || receipt.transactionHash !== transactionHash) {
      throw new TypeError("atomic LaunchGrant consumption receipt crosses its winner request");
    }
    return deepFreeze({ outcome: result.outcome, receipt, executionProofHash: executionProof.proofHash });
  }
  if (result.receipt !== null) {
    throw new TypeError("non-winning atomic LaunchGrant outcome cannot forge a receipt");
  }
  return deepFreeze({ outcome: result.outcome, receipt: null, executionProofHash: executionProof.proofHash });
}

export async function consumeLaunchGrantThroughAuthorityV2(input: Readonly<{
  capability: LaunchGrantAuthorityCapabilityV2;
  context: Omit<LaunchGrantExecutionContextV2,
    "securityControlHead" | "sourceCurrentnessHead" | "sourceCurrentnessVerifier"
    | "liveControlObservationVerifier" | "stateHead" | "nowEpochSeconds">;
  verifiedWalletIntent: VerifiedLaunchGrantWalletIntentV2;
  winnerReservation: LaunchGrantWinnerReservationClaimV2;
  permit: ExecutionPermitV2;
  transactionHash: EvmBytes32V1;
  idempotencyKeyHash: Sha256Digest;
}>): Promise<Readonly<{
  outcome: LaunchGrantAtomicConsumptionOutcomeV2;
  receipt: Readonly<LaunchGrantConsumptionReceiptV2> | null;
  executionProofHash: Sha256Digest;
}>> {
  const context = await observeLaunchGrantAuthorityContextV2({
    capability: input.capability,
    descriptor: input.context.descriptor,
    catalog: input.context.catalog,
    grant: input.context.grant,
    expected: input.context.expected,
    terminalReconciliationOnly: true,
  });
  const resolver = requireLaunchGrantAuthorityResolverV2(input.capability);
  const binding = context.descriptor.launchGrantContractBinding;
  if (binding === null) throw new TypeError("Authority consumption lacks an exact Contract binding");
  const terminalContext = assertLaunchGrantTerminalReconciliationContextV2(context);
  const prior = await reconcileAuthorityLifecycleV2({
    resolver,
    context: terminalContext,
    idempotencyKeyHash: input.idempotencyKeyHash,
  });
  if (prior?.state === "CONSUMED_ONCHAIN") {
    if (prior.executionProofHash === null) {
      throw new TypeError("durable consumed Authority record lacks its execution proof");
    }
    return deepFreeze({
      outcome: "ALREADY_CONSUMED" as const,
      receipt: null,
      executionProofHash: prior.executionProofHash,
    });
  }
  if (prior?.state === "REVOKED_ONCHAIN") {
    if (prior.executionProofHash === null) {
      throw new TypeError("durable revoked Authority record lacks its execution proof");
    }
    return deepFreeze({ outcome: "REVOKED" as const, receipt: null,
      executionProofHash: prior.executionProofHash });
  }
  if (prior?.state === "SUSPENDED_ONCHAIN") {
    if (prior.executionProofHash === null) {
      throw new TypeError("durable suspended Authority record lacks its execution proof");
    }
    return deepFreeze({ outcome: "SUSPENDED" as const, receipt: null,
      executionProofHash: prior.executionProofHash });
  }
  if (prior?.state === "LOST_TO_CONCURRENT_WINNER") {
    return deepFreeze({ outcome: "LOST_TO_CONCURRENT_WINNER" as const, receipt: null,
      executionProofHash: prior.executionProofHash ?? canonicalSha256(
        "programmable.router-v2-lost-winner-no-execution-proof.v2",
        { grantDigest: context.grant.grantDigest, idempotencyKeyHash: input.idempotencyKeyHash },
      ) });
  }
  if (prior?.state === "SUBMISSION_STARTED") {
    const consumer = resolver.resolveAtomicConsumer({
      launchGrantContractBindingHash: binding.bindingHash,
      chainId: binding.chainId,
      router: binding.router,
      grantRegistry: binding.grantRegistry,
      grantRegistryRuntimeCodeHash: binding.grantRegistryRuntimeCodeHash,
      grantConsumerSelector: binding.grantConsumerSelector,
    });
    const recovered = await consumer.reconcileSubmittedGrantAtomically({
      launchGrantContractBindingHash: binding.bindingHash,
      grantDigest: terminalContext.grant.grantDigest,
      grantHash: terminalContext.grant.grantHash,
      grantPreimageHash: terminalContext.grant.grantPreimageHash,
      chainId: binding.chainId,
      router: binding.router,
      grantRegistry: binding.grantRegistry,
      grantRegistryRuntimeCodeHash: binding.grantRegistryRuntimeCodeHash,
      grantStateReaderSelector: binding.grantStateReaderSelector,
      grantConsumerSelector: binding.grantConsumerSelector,
      expectedTransactionHash: nonzeroBytes32(input.transactionHash, "recovery transaction"),
      idempotencyKeyHash: sha256(input.idempotencyKeyHash, "grant consumption idempotency key"),
    });
    const recoveryProofHash = canonicalSha256("programmable.router-v2-submission-recovery.v2", {
      grantDigest: terminalContext.grant.grantDigest,
      priorRecordHash: prior.recordHash,
      stateHeadHash: terminalContext.stateHead.headHash,
      outcome: recovered.outcome,
      expectedTransactionHash: nonzeroBytes32(input.transactionHash, "recovery transaction"),
    });
    if (recovered.outcome === "CONSUMED") {
      const receipt = assertLaunchGrantConsumptionReceiptV2(recovered.receipt);
      if (receipt.grantDigest !== terminalContext.grant.grantDigest
        || receipt.transactionHash !== input.transactionHash) {
        throw new TypeError("submission recovery returned a crossed consumption receipt");
      }
      await appendAuthorityLifecycleTransitionV2({
        resolver,
        context: terminalContext,
        idempotencyKeyHash: input.idempotencyKeyHash,
        state: "CONSUMED_ONCHAIN",
        walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
        winnerReservation: input.winnerReservation,
        permit: input.permit,
        executionProofHash: recoveryProofHash,
        transactionHash: input.transactionHash,
      });
      return deepFreeze({ outcome: "ALREADY_CONSUMED" as const, receipt,
        executionProofHash: recoveryProofHash });
    }
    if (recovered.outcome === "REVOKED") {
      await appendAuthorityLifecycleTransitionV2({
        resolver,
        context: terminalContext,
        idempotencyKeyHash: input.idempotencyKeyHash,
        state: "REVOKED_ONCHAIN",
        walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
        winnerReservation: input.winnerReservation,
        permit: input.permit,
        executionProofHash: recoveryProofHash,
      });
      return deepFreeze({ outcome: "REVOKED" as const, receipt: null,
        executionProofHash: recoveryProofHash });
    }
    if (recovered.outcome === "SUSPENDED") {
      await appendAuthorityLifecycleTransitionV2({
        resolver,
        context: terminalContext,
        idempotencyKeyHash: input.idempotencyKeyHash,
        state: "SUSPENDED_ONCHAIN",
        walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
        winnerReservation: input.winnerReservation,
        permit: input.permit,
        executionProofHash: recoveryProofHash,
      });
      return deepFreeze({ outcome: "SUSPENDED" as const, receipt: null,
        executionProofHash: recoveryProofHash });
    }
    if (recovered.outcome === "AMBIGUOUS_PARKED") {
      await appendAuthorityLifecycleTransitionV2({
        resolver,
        context: terminalContext,
        idempotencyKeyHash: input.idempotencyKeyHash,
        state: "PARKED_PROVIDER_OUTAGE",
        walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
        winnerReservation: input.winnerReservation,
        permit: input.permit,
        executionProofHash: recoveryProofHash,
        retryNotBeforeEpochSeconds: decimal(
          recovered.retryNotBeforeEpochSeconds ?? (context.nowEpochSeconds + 1n).toString(),
          64,
          "submission recovery retry time",
        ),
      });
      return deepFreeze({ outcome: "PARKED_RECONCILIATION_REQUIRED" as const, receipt: null,
        executionProofHash: recoveryProofHash });
    }
    if (terminalContext.stateHead.state !== "ACTIVE") {
      throw new TypeError("registry recovery contradicted the terminal grant state");
    }
  }
  if (terminalContext.stateHead.state !== "ACTIVE") {
    throw new TypeError("terminal grant has no durable submission record to reconcile");
  }
  const current = assertLaunchGrantCurrentControlContextV2(context);
  await appendAuthorityLifecycleTransitionV2({
    resolver,
    context: current,
    idempotencyKeyHash: input.idempotencyKeyHash,
    state: "SUBMISSION_STARTED",
    walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
    winnerReservation: input.winnerReservation,
    permit: input.permit,
  });
  const outcome = await consumeLaunchGrantAtomicallyV2({
    context,
    winnerReservationStore: resolver.resolveWinnerReservationStore({
      bindingHash: context.securityControlHead.winnerReservationAuthorityBindingHash,
      keyEpoch: context.securityControlHead.winnerReservationAuthorityKeyEpoch,
    }),
    signer: resolver.resolveSigner({
      bindingHash: context.securityControlHead.signerAuthorityBindingHash,
      keyEpoch: context.securityControlHead.signerKeyEpoch,
    }),
    walletIntentVerifier: resolver.resolveWalletIntentVerifier({
      bindingHash: context.securityControlHead.walletIntentVerifierBindingHash,
      keyEpoch: context.securityControlHead.walletIntentVerifierKeyEpoch,
    }),
    verifiedWalletIntent: input.verifiedWalletIntent,
    winnerReservation: input.winnerReservation,
    permit: input.permit,
    transactionHash: input.transactionHash,
    idempotencyKeyHash: input.idempotencyKeyHash,
    consumer: resolver.resolveAtomicConsumer({
      launchGrantContractBindingHash: binding.bindingHash,
      chainId: binding.chainId,
      router: binding.router,
      grantRegistry: binding.grantRegistry,
      grantRegistryRuntimeCodeHash: binding.grantRegistryRuntimeCodeHash,
      grantConsumerSelector: binding.grantConsumerSelector,
    }),
  });
  await appendAuthorityLifecycleTransitionV2({
    resolver,
    context: current,
    idempotencyKeyHash: input.idempotencyKeyHash,
    state: outcome.outcome === "CONSUMED"
      ? "CONSUMED_ONCHAIN"
      : outcome.outcome === "SUSPENDED"
        ? "SUSPENDED_ONCHAIN"
      : outcome.outcome === "REVOKED"
        ? "REVOKED_ONCHAIN"
        : "LOST_TO_CONCURRENT_WINNER",
    walletIntentHash: input.verifiedWalletIntent.walletIntentHash,
    winnerReservation: input.winnerReservation,
    permit: input.permit,
    executionProofHash: outcome.executionProofHash,
    transactionHash: outcome.outcome === "CONSUMED" ? input.transactionHash : null,
  });
  return outcome;
}

export function createLaunchGrantConsumptionReceiptV2(
  raw: Omit<LaunchGrantConsumptionReceiptV2,
    "consumptionHash" | "schemaVersion" | "state">,
): Readonly<LaunchGrantConsumptionReceiptV2> {
  exactKeys(raw, [
    "blockHash", "blockNumber", "grantDigest", "previousStateHeadHash",
    "registryEvidenceSha256", "transactionHash",
  ], "launch grant consumption receipt input");
  const core = {
    schemaVersion: "programmable.router-v2-launch-grant-consumption-receipt.v2" as const,
    grantDigest: nonzeroBytes32(raw.grantDigest, "consumption grant digest"),
    previousStateHeadHash: sha256(raw.previousStateHeadHash, "consumption state head"),
    state: "CONSUMED" as const,
    transactionHash: nonzeroBytes32(raw.transactionHash, "consumption transaction"),
    blockNumber: positiveDecimal(raw.blockNumber, "consumption block number"),
    blockHash: nonzeroBytes32(raw.blockHash, "consumption block hash"),
    registryEvidenceSha256: sha256(raw.registryEvidenceSha256, "consumption registry evidence"),
  };
  return deepFreeze({ ...core, consumptionHash: canonicalSha256(core.schemaVersion, core) });
}

export function assertLaunchGrantConsumptionReceiptV2(
  raw: LaunchGrantConsumptionReceiptV2,
): Readonly<LaunchGrantConsumptionReceiptV2> {
  plainRecord(raw, "launch grant consumption receipt");
  const { consumptionHash: _hash, schemaVersion: _schema, state: _state, ...input } = raw;
  return exactArtifact(raw, createLaunchGrantConsumptionReceiptV2(input),
    "launch grant consumption receipt");
}

