export function createCanonicalLaunchReceiptV2(
  grantRaw: LaunchGrantV2,
  consumptionRaw: LaunchGrantConsumptionReceiptV2,
  receiptEventVerifier: LaunchGrantReceiptEventVerifierPortV2,
  verifiedEventRaw: VerifiedLaunchGrantReceiptEventV2,
): Readonly<CanonicalLaunchReceiptV2> {
  const grant = assertLaunchGrantShapeV2(grantRaw);
  const consumption = assertLaunchGrantConsumptionReceiptV2(consumptionRaw);
  const event = assertVerifiedLaunchGrantReceiptEventV2(receiptEventVerifier, verifiedEventRaw);
  const binding = grant.launchGrantContractBindingHash;
  if (event.launchGrantContractBindingHash !== binding
    || event.grantDigest !== grant.grantDigest || event.grantHash !== grant.grantHash
    || event.grantConsumptionHash !== consumption.consumptionHash
    || event.chainId !== grant.chainId || event.router !== grant.router
    || event.transactionHash !== consumption.transactionHash
    || event.transactionSender !== grant.launchWallet
    || event.transactionTo !== grant.action.to
    || event.transactionDataSha256 !== grant.action.transactionDataSha256
    || event.transactionValueWei !== grant.action.valueWei
    || event.blockNumber !== consumption.blockNumber || event.blockHash !== consumption.blockHash) {
    throw new TypeError("verified launch receipt event crosses its exact grant consumption");
  }
  const core = {
    schemaVersion: "programmable.router-v2-canonical-launch-receipt.v2" as const,
    receiptVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2,
    grantHash: grant.grantHash,
    grantDigest: grant.grantDigest,
    grantConsumptionHash: consumption.consumptionHash,
    planHash: grant.planHash,
    builderEvidenceHash: grant.builderEvidenceHash,
    reviewerAttestationHash: grant.reviewerAttestationHash,
    profileDescriptorHash: grant.profileDescriptorHash,
    reviewGeneration: grant.reviewGeneration,
    reviewGenerationHash: grant.reviewGenerationHash,
    securityEpoch: grant.securityEpoch,
    securityEpochHash: grant.securityEpochHash,
    policyEpoch: grant.policyEpoch,
    policyEpochHash: grant.policyEpochHash,
    chainId: grant.chainId,
    router: grant.router,
    routerRuntimeCodeHash: grant.routerRuntimeCodeHash,
    launchWallet: grant.launchWallet,
    transactionHash: consumption.transactionHash,
    transactionSender: event.transactionSender,
    transactionTo: grant.action.to,
    transactionNonce: event.transactionNonce,
    transactionDataSha256: grant.action.transactionDataSha256,
    transactionValueWei: grant.action.valueWei,
    blockNumber: consumption.blockNumber,
    blockHash: consumption.blockHash,
    launchId: grant.launchId,
    componentGraphHash: grant.componentGraphHash,
    componentIdentities: grant.componentIdentities,
    componentIdentitiesHash: grant.componentIdentitiesHash,
    exactRuntimeBindings: grant.exactRuntimeBindings,
    expectedRuntimeCodehashSetHash: grant.expectedRuntimeCodehashSetHash,
    configurationHash: grant.configurationHash,
    poolKeyHash: grant.poolKeyHash,
    poolId: grant.poolId,
    resultHash: grant.resultHash,
    executionTimingHash: grant.executionTimingHash,
    verifiedReceiptEventHash: event.receiptEventHash,
    receiptVerifierBindingHash: event.receiptVerifierBindingHash,
    receiptVerifierKeyEpoch: event.receiptVerifierKeyEpoch,
    launchStampHash: event.launchStampHash,
    authenticatedReceiptEvidenceSha256: event.authenticatedReceiptEvidenceSha256,
  };
  return deepFreeze({ ...core, receiptHash: canonicalSha256(core.schemaVersion, core) });
}

export async function createCanonicalLaunchReceiptThroughAuthorityV2(input: Readonly<{
  capability: LaunchGrantAuthorityCapabilityV2;
  descriptor: LaunchProfileDescriptorV2;
  catalog: LaunchProfileCatalogV2;
  grant: LaunchGrantV2;
  consumption: LaunchGrantConsumptionReceiptV2;
  verifiedReceiptEvent: VerifiedLaunchGrantReceiptEventV2;
}>): Promise<Readonly<CanonicalLaunchReceiptV2>> {
  const resolver = requireLaunchGrantAuthorityResolverV2(input.capability);
  const descriptor = assertLaunchProfileDescriptorV2(input.descriptor);
  const catalog = assertLaunchProfileCatalogV2(input.catalog);
  const grant = assertLaunchGrantShapeV2(input.grant);
  const binding = descriptor.launchGrantContractBinding;
  if (binding === null || descriptor.state !== "ENABLED" || !descriptor.activationAllowed
    || !catalog.descriptors.some(({ descriptorHash }) => descriptorHash === descriptor.descriptorHash)
    || grant.profileDescriptorHash !== descriptor.descriptorHash
    || grant.launchGrantContractBindingHash !== binding.bindingHash) {
    throw new TypeError("canonical receipt crosses its exact profile catalog");
  }
  const event = assertVerifiedLaunchGrantReceiptEventShapeV2(input.verifiedReceiptEvent);
  if (event.launchGrantContractBindingHash !== binding.bindingHash
    || event.chainId !== binding.chainId || event.router !== binding.router
    || event.grantRegistry !== binding.grantRegistry
    || event.grantRegistryRuntimeCodeHash !== binding.grantRegistryRuntimeCodeHash
    || event.grantConsumerSelector !== binding.grantConsumerSelector) {
    throw new TypeError("canonical receipt event crosses its frozen Contract binding");
  }
  // A kill switch stops a new launch, never the immutable receipt/finality of
  // a launch already consumed onchain. The resolver only returns historical
  // verifier keys it still recognizes for this exact event binding.
  const verifier = resolver.resolveReceiptEventVerifier({
    bindingHash: event.receiptVerifierBindingHash,
    keyEpoch: event.receiptVerifierKeyEpoch,
    launchGrantContractBindingHash: grant.launchGrantContractBindingHash,
    grantDigest: grant.grantDigest,
    grantHash: grant.grantHash,
  });
  return createCanonicalLaunchReceiptV2(
    grant,
    input.consumption,
    verifier,
    event,
  );
}

