export function createFinalityIndexingReceiptV2(
  grantRaw: LaunchGrantV2,
  consumptionRaw: LaunchGrantConsumptionReceiptV2,
  launchReceiptRaw: CanonicalLaunchReceiptV2,
  raw: Omit<FinalityIndexingReceiptV2,
    "appendOnlyStatus" | "canonicalLaunchReceiptHash" | "canonicalReceiptIdentityImmutable"
    | "chainId" | "grantDigest" | "launchStampHash" | "receiptHash" | "receiptVersion"
    | "schemaVersion" | "transactionHash">,
  previousRaw?: FinalityIndexingReceiptV2,
): Readonly<FinalityIndexingReceiptV2> {
  exactKeys(raw, [
    "finalityEvidenceSha256", "finalizedBlockHash", "finalizedBlockNumber",
    "indexingEvidenceSha256", "indexingStatus", "supersedesReceiptHash",
  ], "finality indexing receipt v2 input");
  const launchReceipt = assertCanonicalLaunchReceiptV2(
    grantRaw,
    consumptionRaw,
    launchReceiptRaw,
  );
  const finalizedBlockNumber = positiveDecimal(raw.finalizedBlockNumber, "finalized block number");
  if (BigInt(finalizedBlockNumber) < BigInt(launchReceipt.blockNumber)) {
    throw new TypeError("finality precedes the canonical launch receipt");
  }
  if (!( ["FINALIZED_PENDING_INDEXING", "FINALIZED_INDEXED"] as const)
    .includes(raw.indexingStatus)) {
    throw new TypeError("finality indexing status is invalid");
  }
  const indexingEvidenceSha256 = raw.indexingEvidenceSha256 === null
    ? null : sha256(raw.indexingEvidenceSha256, "indexing evidence");
  if ((raw.indexingStatus === "FINALIZED_INDEXED") !== (indexingEvidenceSha256 !== null)) {
    throw new TypeError("finality indexing evidence is inconsistent with its status");
  }
  let supersedesReceiptHash: Sha256Digest | null = null;
  if (previousRaw === undefined) {
    if (raw.supersedesReceiptHash !== null || raw.indexingStatus !== "FINALIZED_PENDING_INDEXING") {
      throw new TypeError("initial finality receipt must begin pending without a predecessor");
    }
  } else {
    const previous = assertFinalityIndexingReceiptV2(
      grantRaw,
      consumptionRaw,
      launchReceipt,
      previousRaw,
    );
    if (previous.grantDigest !== launchReceipt.grantDigest
      || previous.canonicalLaunchReceiptHash !== launchReceipt.receiptHash
      || previous.chainId !== launchReceipt.chainId
      || previous.transactionHash !== launchReceipt.transactionHash
      || previous.launchStampHash !== launchReceipt.launchStampHash
      || previous.indexingStatus !== "FINALIZED_PENDING_INDEXING"
      || previous.supersedesReceiptHash !== null
      || previous.indexingEvidenceSha256 !== null
      || raw.indexingStatus !== "FINALIZED_INDEXED"
      || raw.supersedesReceiptHash !== previous.receiptHash
      || BigInt(finalizedBlockNumber) < BigInt(previous.finalizedBlockNumber)
      || (finalizedBlockNumber === previous.finalizedBlockNumber
        && raw.finalizedBlockHash !== previous.finalizedBlockHash)) {
      throw new TypeError("finality receipt is not a monotonic same-grant append-only transition");
    }
    supersedesReceiptHash = previous.receiptHash;
  }
  const core = {
    schemaVersion: "programmable.router-v2-finality-indexing-receipt.v2" as const,
    receiptVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2,
    grantDigest: launchReceipt.grantDigest,
    canonicalLaunchReceiptHash: launchReceipt.receiptHash,
    chainId: launchReceipt.chainId,
    transactionHash: launchReceipt.transactionHash,
    launchStampHash: launchReceipt.launchStampHash,
    finalizedBlockNumber,
    finalizedBlockHash: nonzeroBytes32(raw.finalizedBlockHash, "finalized block hash"),
    finalityEvidenceSha256: sha256(raw.finalityEvidenceSha256, "finality evidence"),
    indexingStatus: raw.indexingStatus,
    indexingEvidenceSha256,
    supersedesReceiptHash,
    canonicalReceiptIdentityImmutable: true as const,
    appendOnlyStatus: true as const,
  };
  return deepFreeze({ ...core, receiptHash: canonicalSha256(core.schemaVersion, core) });
}

export function assertFinalityIndexingReceiptV2(
  grant: LaunchGrantV2,
  consumption: LaunchGrantConsumptionReceiptV2,
  launchReceipt: CanonicalLaunchReceiptV2,
  raw: FinalityIndexingReceiptV2,
  previous?: FinalityIndexingReceiptV2,
): Readonly<FinalityIndexingReceiptV2> {
  plainRecord(raw, "finality indexing receipt v2");
  const {
    appendOnlyStatus: _append, canonicalLaunchReceiptHash: _launch,
    canonicalReceiptIdentityImmutable: _immutable, chainId: _chain, grantDigest: _digest,
    launchStampHash: _stamp, receiptHash: _hash, receiptVersion: _version,
    schemaVersion: _schema, transactionHash: _tx, ...input
  } = raw;
  return exactArtifact(raw, createFinalityIndexingReceiptV2(
    grant,
    consumption,
    launchReceipt,
    input,
    previous,
  ),
    "finality indexing receipt v2");
}

