  readonly grantState: LaunchGrantStateV2;
  readonly profileDescriptorHash: Sha256Digest;
  readonly planHash: Sha256Digest;
  readonly launchWallet: EvmAddressV1;
  readonly chainId: string;
  readonly router: EvmAddressV1;
  readonly action: Readonly<VerifiedWalletActionV1>;
  readonly actionCommitment: Sha256Digest;
  readonly executionTiming: LaunchExecutionTimingV2;
  readonly currentnessHash: Sha256Digest | null;
  readonly launchable: boolean;
  readonly approvalPresentation:
    | "APPROVED_LAUNCH_ANYTIME"
    | "APPROVED_SCHEDULE_ANCHOR_REQUIRED"
    | "RE_REVIEW_REBIND_REQUIRED"
    | "APPROVAL_UNCHANGED_LAUNCH_UNAVAILABLE"
    | "GRANT_SUSPENDED_REVIEW_SUCCESSOR_REQUIRED"
    | "GRANT_REVOKED_OR_CONSUMED";
  readonly legacyTransportVisibleToApplicant: false;
