export type RouterV2LifecycleArtifactV2 =
  | LaunchProfileDescriptorV2
  | ApplicantLaunchPlanV2
  | BuilderEvidenceCommitmentV2
  | ReviewerAuthorityAttestationV2
  | LaunchGrantV2
  | ExecutionPermitV2
  | CanonicalLaunchReceiptV2
  | FinalityIndexingReceiptV2;

export interface CanonicalLifecycleBytesV2 {
  readonly schemaVersion: "programmable.router-v2-canonical-lifecycle-bytes.v2";
  readonly artifactSchemaVersion: RouterV2LifecycleArtifactV2["schemaVersion"];
  readonly artifactHash: Sha256Digest;
  readonly byteLength: number;
  readonly bytesSha256: Sha256Digest;
  readonly bytes: Uint8Array;
}

export function encodeRouterV2LifecycleCanonicalBytesV2(
  artifact: RouterV2LifecycleArtifactV2,
): Readonly<CanonicalLifecycleBytesV2> {
  const artifactHash = assertLifecycleArtifactSelfHashV2(artifact);
  const bytes = Uint8Array.from(Buffer.from(canonicalizeJson(artifact), "utf8"));
  if (bytes.byteLength > 1_048_576) throw new TypeError("lifecycle v2 artifact exceeds 1 MiB");
  return Object.freeze({
    schemaVersion: "programmable.router-v2-canonical-lifecycle-bytes.v2" as const,
    artifactSchemaVersion: artifact.schemaVersion,
    artifactHash,
    byteLength: bytes.byteLength,
    bytesSha256: rawBytesSha256(bytes),
    bytes,
  });
}

export function assertRouterV2LifecycleCanonicalBytesV2(
  artifact: RouterV2LifecycleArtifactV2,
  bytes: Uint8Array,
): void {
  if (!(bytes instanceof Uint8Array) || bytes.byteLength > 1_048_576) {
    throw new TypeError("canonical lifecycle v2 bytes are invalid");
  }
  const text = Buffer.from(bytes).toString("utf8");
  const parsed = parseStrictJson(text, { maximumBytes: 1_048_576, maximumDepth: 128 });
  if (canonicalizeJson(parsed) !== text || text !== canonicalizeJson(artifact)) {
    throw new TypeError("lifecycle v2 artifact bytes are noncanonical or drifted");
  }
  assertLifecycleArtifactSelfHashV2(artifact);
}

export function assertLaunchGrantCanonicalBytesV2(bytes: Uint8Array): Readonly<LaunchGrantV2> {
  if (!(bytes instanceof Uint8Array) || bytes.byteLength > 1_048_576) {
    throw new TypeError("LaunchGrant canonical bytes are invalid");
  }
  const text = Buffer.from(bytes).toString("utf8");
  const parsed = parseStrictJson(text, { maximumBytes: 1_048_576, maximumDepth: 128 });
  if (canonicalizeJson(parsed) !== text || !isRecord(parsed)
    || parsed.schemaVersion !== "programmable.router-v2-launch-grant.v2") {
    throw new TypeError("legacy permit bytes cannot be reinterpreted as LaunchGrant bytes");
  }
  return assertLaunchGrantShapeV2(JSON.parse(text) as LaunchGrantV2);
}

function assertLaunchGrantShapeV2(raw: LaunchGrantV2): Readonly<LaunchGrantV2> {
  exactKeys(raw, [
    "action", "actionCommitment", "applicantIdHash", "builderEvidenceHash", "catalogGeneration",
    "catalogHash", "chainId", "componentGraphHash", "componentIdentities", "componentIdentitiesHash",
    "configurationHash", "exactRuntimeBindings", "expectedRuntimeCodehashSetHash", "expiresAtEpochSeconds",
    "grantCompilerArtifactSha256", "grantDigest", "grantHash", "grantNonce",
    "grantPreimageHash", "grantVersion", "issuedAt", "launchGrantContractBindingHash",
    "launchId", "launchWallet", "noDefaultExpiry", "planHash", "policyEpoch", "policyEpochHash", "poolId",
    "poolKeyHash", "profileDescriptorHash", "resultHash", "executionTiming",
    "executionTimingHash", "reviewGeneration", "reviewGenerationHash", "revocationGeneration", "router",
    "routerRuntimeCodeHash", "schemaVersion", "securityEpoch", "securityEpochHash",
    "sourceCommit", "sourceRepository",
    "sourceHeadCommit", "sourceTree", "stateAtIssuance", "reviewerAttestationHash",
  ], "LaunchGrant v2");
  if (raw.schemaVersion !== "programmable.router-v2-launch-grant.v2"
    || raw.grantVersion !== ROUTER_V2_SHARED_LIFECYCLE_VERSION_V2
    || raw.stateAtIssuance !== "ACTIVE" || raw.noDefaultExpiry !== true
    || raw.expiresAtEpochSeconds !== null) {
    throw new TypeError("LaunchGrant version, issuance state or evergreen policy is invalid");
  }
  const action = assertVerifiedWalletActionShapeV2(raw.action);
  const preimage = deepFreeze({
    applicantIdHash: sha256(raw.applicantIdHash, "grant applicant"),
    sourceRepository: repository(raw.sourceRepository),
    sourceCommit: gitObject(raw.sourceCommit, "grant source commit"),
    sourceHeadCommit: gitObject(raw.sourceHeadCommit, "grant source head commit"),
    sourceTree: gitObject(raw.sourceTree, "grant source tree"),
    profileDescriptorHash: sha256(raw.profileDescriptorHash, "grant profile descriptor"),
    launchGrantContractBindingHash: sha256(
      raw.launchGrantContractBindingHash, "grant Contract binding",
    ),
    planHash: sha256(raw.planHash, "grant plan"),
    builderEvidenceHash: sha256(raw.builderEvidenceHash, "grant builder evidence"),
    reviewerAttestationHash: sha256(raw.reviewerAttestationHash, "grant reviewer attestation"),
    chainId: positiveDecimal(raw.chainId, "grant chain id"),
    router: nonzeroAddress(raw.router, "grant router"),
    routerRuntimeCodeHash: nonzeroBytes32(raw.routerRuntimeCodeHash, "grant router runtime"),
    launchWallet: nonzeroAddress(raw.launchWallet, "grant launch wallet"),
    componentGraphHash: nonzeroBytes32(raw.componentGraphHash, "grant component graph"),
    componentIdentities: normalizeLaunchComponentIdentitiesV2(
      raw.componentIdentities,
      "grant component identities",
    ),
    componentIdentitiesHash: sha256(raw.componentIdentitiesHash, "grant component identities"),
    exactRuntimeBindings: normalizeRuntimeBindingsV2(
      raw.exactRuntimeBindings,
      "grant runtime bindings",
    ),
    expectedRuntimeCodehashSetHash: sha256(
      raw.expectedRuntimeCodehashSetHash, "grant runtime codehash set",
    ),
    configurationHash: nonzeroBytes32(raw.configurationHash, "grant configuration"),
    poolKeyHash: nullableBytes32(raw.poolKeyHash, "grant pool key"),
    poolId: nullableBytes32(raw.poolId, "grant pool id"),
    resultHash: nonzeroBytes32(raw.resultHash, "grant result"),
    launchId: nonzeroBytes32(raw.launchId, "grant launch id"),
    executionTimingHash: sha256(raw.executionTimingHash, "grant execution timing"),
    actionCommitment: sha256(raw.actionCommitment, "grant action commitment"),
    reviewGeneration: positiveDecimal(raw.reviewGeneration, "grant review generation"),
    reviewGenerationHash: sha256(raw.reviewGenerationHash, "grant review generation hash"),
    securityEpoch: positiveDecimal(raw.securityEpoch, "grant security epoch"),
    securityEpochHash: sha256(raw.securityEpochHash, "grant security epoch hash"),
    policyEpoch: positiveDecimal(raw.policyEpoch, "grant policy epoch"),
    policyEpochHash: sha256(raw.policyEpochHash, "grant policy epoch hash"),
    catalogHash: sha256(raw.catalogHash, "grant catalog"),
    catalogGeneration: positiveDecimal(raw.catalogGeneration, "grant catalog generation"),
    revocationGeneration: decimal(raw.revocationGeneration, 64, "grant revocation generation"),
    grantNonce: nonzeroBytes32(raw.grantNonce, "grant nonce"),
  });
  if (action.actionCommitment !== preimage.actionCommitment
    || action.chainId !== preimage.chainId || action.from !== preimage.launchWallet
    || action.to !== preimage.router) {
    throw new TypeError("LaunchGrant verified action crosses its exact preimage");
  }
  const grantPreimageHash = sha256(raw.grantPreimageHash, "grant preimage");
  if (grantPreimageHash
    !== canonicalSha256("programmable.router-v2-launch-grant-preimage.v2", preimage)) {
    throw new TypeError("LaunchGrant preimage hash is invalid");
  }
  const executionTiming = assertLaunchExecutionTimingV2(
    action.capabilitySemantics,
    raw.executionTiming.kind === "SOURCE_SCHEDULE_ANCHOR" ? "OPTIONAL" : "FORBIDDEN",
    raw.executionTiming,
  );
  if (executionTiming.timingHash !== preimage.executionTimingHash) {
    throw new TypeError("LaunchGrant execution timing crosses its exact preimage");
  }
  const core = {
    schemaVersion: raw.schemaVersion,
    grantVersion: raw.grantVersion,
    stateAtIssuance: raw.stateAtIssuance,
    noDefaultExpiry: raw.noDefaultExpiry,
    expiresAtEpochSeconds: raw.expiresAtEpochSeconds,
    ...preimage,
    executionTiming,
    action,
    issuedAt: instant(raw.issuedAt, "grant issue time"),
    grantPreimageHash,
    grantCompilerArtifactSha256: sha256(
      raw.grantCompilerArtifactSha256, "grant compiler artifact",
    ),
    grantDigest: nonzeroBytes32(raw.grantDigest, "grant digest"),
  };
  if (canonicalSha256(core.schemaVersion, core) !== raw.grantHash) {
    throw new TypeError("LaunchGrant self hash is invalid");
  }
  return deepFreeze({ ...core, grantHash: raw.grantHash });
}

