export function createLaunchProfileCatalogV1(
  rawDescriptors: readonly LaunchProfileDescriptorV1[],
): Readonly<LaunchProfileCatalogV1> {
  if (!Array.isArray(rawDescriptors) || rawDescriptors.length < 1 || rawDescriptors.length > 64) {
    throw new TypeError("launch profile catalog cardinality is invalid");
  }
  const descriptors = rawDescriptors.map(assertLaunchProfileDescriptorV1)
    .sort((left, right) => compareUtf8(left.slotId, right.slotId));
  unique(descriptors.map(({ slotId }) => slotId), "profile slot ids");
  const boundKeys = descriptors.flatMap(({ exactContractBinding }) => exactContractBinding === null
    ? []
    : [`${exactContractBinding.chainId}:${exactContractBinding.routerFamily}:${exactContractBinding.profileKey}`]);
  unique(boundKeys, "bound profile keys");
  const core = {
    schemaVersion: "programmable.router-v2-launch-profile-catalog.v1" as const,
    catalogVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V1,
    descriptors: deepFreeze(descriptors),
  };
  return deepFreeze({ ...core, catalogHash: canonicalSha256(core.schemaVersion, core) });
}

