export interface ExactTypedActionArtifactSourceV1 {
  /** Returns the immutable bytes addressed by artifactSha256; no mutable URL is accepted. */
  loadTypedActionCanonicalBytes(
    artifactSha256: Sha256Digest,
  ): Promise<Uint8Array>;
}

export interface ExactTypedActionCompilerPortV1 {
  /**
   * The implementation is profile-release-bound and must decode the exact action schema,
   * recompute component init-code/address/runtime expectations, then emit transaction bytes.
   */
  verifyAndCompileExactTypedAction(input: Readonly<{
    descriptor: LaunchProfileDescriptorV1;
    plan: ApplicantLaunchPlanV1;
    exactContractBinding: ExactContractProfileBindingV1;
    typedActionCanonicalBytes: Uint8Array;
  }>): Promise<Readonly<{
    decodedTypedFieldsHash: EvmBytes32V1;
    componentCreationEvidenceSha256: Sha256Digest;
    compilerVerificationEvidenceSha256: Sha256Digest;
    transactionDataBytes: Uint8Array;
  }>>;
}

export async function compileVerifiedWalletActionV1(input: Readonly<{
  descriptor: LaunchProfileDescriptorV1;
  plan: ApplicantLaunchPlanV1;
  artifactSource: ExactTypedActionArtifactSourceV1;
  compiler: ExactTypedActionCompilerPortV1;
  typedActionArtifactSha256: Sha256Digest;
  chainId: string;
  from: EvmAddressV1;
  to: EvmAddressV1;
  valueWei: string;
}>): Promise<Readonly<{
  action: Readonly<VerifiedWalletActionV1>;
  transactionDataBytes: Uint8Array;
}>> {
  const descriptor = assertLaunchProfileDescriptorV1(input.descriptor);
  const plan = assertApplicantLaunchPlanV1(descriptor, input.plan);
  const binding = descriptor.exactContractBinding;
  if (binding === null) throw new TypeError("typed action compiler lacks an exact contract freeze");
  const artifactSha256 = sha256(input.typedActionArtifactSha256, "typed action artifact");
  const typedActionCanonicalBytes = Uint8Array.from(
    await input.artifactSource.loadTypedActionCanonicalBytes(artifactSha256),
  );
  if (typedActionCanonicalBytes.byteLength < 1 || typedActionCanonicalBytes.byteLength > 1_048_576
    || rawBytesSha256(typedActionCanonicalBytes) !== artifactSha256) {
    throw new TypeError("typed action artifact bytes do not match their content address");
  }
  const compiled = await input.compiler.verifyAndCompileExactTypedAction({
    descriptor,
    plan,
    exactContractBinding: binding,
    typedActionCanonicalBytes: Uint8Array.from(typedActionCanonicalBytes),
  });
  if (!(compiled.transactionDataBytes instanceof Uint8Array)
    || compiled.transactionDataBytes.byteLength < 4
    || compiled.transactionDataBytes.byteLength > 1_048_576) {
    throw new TypeError("exact typed action compiler returned invalid transaction bytes");
  }
  const transactionDataBytes = Uint8Array.from(compiled.transactionDataBytes);
  const action = createVerifiedWalletActionV1(descriptor, plan, {
    chainId: input.chainId,
    from: input.from,
    to: input.to,
    valueWei: input.valueWei,
    typedActionArtifactSha256: artifactSha256,
    typedActionCanonicalBytesSha256: rawBytesSha256(typedActionCanonicalBytes),
    typedActionCanonicalBytesLength: typedActionCanonicalBytes.byteLength.toString(10),
    decodedTypedFieldsHash: compiled.decodedTypedFieldsHash,
    componentCreationEvidenceSha256: compiled.componentCreationEvidenceSha256,
    compilerVerificationEvidenceSha256: compiled.compilerVerificationEvidenceSha256,
    transactionDataSha256: rawBytesSha256(transactionDataBytes),
    typedActionSemanticHash: plan.compiledActionSemanticHash,
  });
  return Object.freeze({ action, transactionDataBytes });
}

