export function createSecurityControlHeadV1(
  raw: Omit<SecurityControlHeadV1, "headHash" | "schemaVersion">,
): Readonly<SecurityControlHeadV1> {
  exactKeys(raw, [
    "catalogGeneration", "catalogHash", "expiresAtEpochSeconds", "globalKillSwitch",
    "observedAtEpochSeconds", "revocationGeneration", "securityEpoch",
    "suspendedProfileDescriptorHashes",
  ], "security control head input");
  const observedAt = decimal(raw.observedAtEpochSeconds, 64, "control observation time");
  const expiresAt = decimal(raw.expiresAtEpochSeconds, 64, "control expiry");
  if (BigInt(expiresAt) <= BigInt(observedAt)
    || BigInt(expiresAt) - BigInt(observedAt) > ROUTER_V2_MAXIMUM_CURRENTNESS_SECONDS_V1) {
    throw new TypeError("security control head currentness window is invalid");
  }
  const suspended = shaSet(raw.suspendedProfileDescriptorHashes, "suspended profile descriptor");
  const core = {
    schemaVersion: "programmable.router-v2-security-control-head.v1" as const,
    catalogHash: sha256(raw.catalogHash, "security control catalog"),
    catalogGeneration: positiveDecimal(raw.catalogGeneration, "security catalog generation"),
    revocationGeneration: decimal(raw.revocationGeneration, 64, "security revocation generation"),
    securityEpoch: positiveDecimal(raw.securityEpoch, "security epoch"),
    globalKillSwitch: strictBoolean(raw.globalKillSwitch, "global kill switch"),
    suspendedProfileDescriptorHashes: suspended,
    observedAtEpochSeconds: observedAt,
    expiresAtEpochSeconds: expiresAt,
  };
  return deepFreeze({ ...core, headHash: canonicalSha256(core.schemaVersion, core) });
}

export function assertSecurityControlHeadV1(
  raw: SecurityControlHeadV1,
): Readonly<SecurityControlHeadV1> {
  const { headHash: _headHash, schemaVersion: _schemaVersion, ...input } = raw;
  return exactArtifact(raw, createSecurityControlHeadV1(input), "security control head");
}

export type ExecutionPermitDenialCodeV1 =
  | "PROFILE_NOT_ENABLED"
  | "REVIEW_NOT_APPROVED"
  | "STALE_OR_REVOKED_CONTROL_HEAD"
  | "GLOBAL_KILL_SWITCH_ACTIVE"
  | "PROFILE_SUSPENDED"
  | "WALLET_INTENT_STALE"
  | "PERMIT_WINDOW_INVALID"
  | "WINNER_NOT_RESERVED"
  | "ARTIFACT_MISMATCH";

export type ExecutionPermitEvaluationV1 = Readonly<
  | {
    readonly authorityDecision: "ALLOW_BOUND_PERMIT";
    readonly denialCode: null;
    readonly permit: Readonly<ExecutionPermitV1>;
    readonly decisionHash: Sha256Digest;
  }
  | {
    readonly authorityDecision: "DENY";
    readonly denialCode: ExecutionPermitDenialCodeV1;
    readonly permit: null;
    readonly decisionHash: Sha256Digest;
  }
>;

export function evaluateExecutionPermitV1(input: Readonly<{
  descriptor: LaunchProfileDescriptorV1;
  plan: ApplicantLaunchPlanV1;
  evidence: BuilderEvidenceCommitmentV1;
  reviewerAttestation: ReviewerAuthorityAttestationV1;
  action: VerifiedWalletActionV1;
  walletIntent: AuthenticatedWalletIntentV1;
  securityControlHead: SecurityControlHeadV1;
  winnerKeyHash: Sha256Digest;
  winnerReservationClaim: WinnerReservationClaimV1 | null;
  permitNonce: EvmBytes32V1;
  contractPermitDigest: EvmBytes32V1;
  validAfterEpochSeconds: string;
  deadlineEpochSeconds: string;
  signerAuthorityBindingHash: Sha256Digest;
  signatureArtifactSha256: Sha256Digest;
  nowEpochSeconds: bigint;
}>): ExecutionPermitEvaluationV1 {
  try {
    const descriptor = assertLaunchProfileDescriptorV1(input.descriptor);
    if (descriptor.state !== "ENABLED" || !descriptor.activationAllowed
      || descriptor.exactContractBinding === null) return permitDenial("PROFILE_NOT_ENABLED");
    const plan = assertApplicantLaunchPlanV1(descriptor, input.plan);
    const evidence = assertBuilderEvidenceCommitmentV1(descriptor, plan, input.evidence);
    const reviewerAttestation = assertReviewerAuthorityAttestationV1(
      descriptor,
      plan,
      evidence,
      input.reviewerAttestation,
    );
    if (reviewerAttestation.decision !== "APPROVED") return permitDenial("REVIEW_NOT_APPROVED");
    const action = assertVerifiedWalletActionV1(descriptor, plan, input.action);
    const walletIntent = assertAuthenticatedWalletIntentV1(plan, action, input.walletIntent);
    const control = assertSecurityControlHeadV1(input.securityControlHead);
    if (control.globalKillSwitch) return permitDenial("GLOBAL_KILL_SWITCH_ACTIVE");
    if (control.suspendedProfileDescriptorHashes.includes(descriptor.descriptorHash)) {
      return permitDenial("PROFILE_SUSPENDED");
    }
    const binding = descriptor.exactContractBinding;
    if (control.catalogHash !== reviewerAttestation.catalogHash
      || control.catalogGeneration !== reviewerAttestation.catalogGeneration
      || control.revocationGeneration !== reviewerAttestation.revocationGeneration
      || control.securityEpoch !== binding.securityEpoch
      || control.securityEpoch !== reviewerAttestation.securityEpoch
      || BigInt(control.observedAtEpochSeconds) > input.nowEpochSeconds
      || BigInt(control.expiresAtEpochSeconds) <= input.nowEpochSeconds) {
      return permitDenial("STALE_OR_REVOKED_CONTROL_HEAD");
    }
    if (BigInt(walletIntent.issuedAtEpochSeconds) > input.nowEpochSeconds
      || BigInt(walletIntent.expiresAtEpochSeconds) <= input.nowEpochSeconds) {
      return permitDenial("WALLET_INTENT_STALE");
    }
    if (input.winnerReservationClaim === null) return permitDenial("WINNER_NOT_RESERVED");
    const winnerReservation = assertWinnerReservationClaimV1(input.winnerReservationClaim);
    if (winnerReservation.winnerKeyHash !== input.winnerKeyHash
      || winnerReservation.planHash !== plan.planHash
      || winnerReservation.permitDigest !== input.contractPermitDigest) {
      return permitDenial("WINNER_NOT_RESERVED");
    }
    const validAfter = BigInt(decimal(input.validAfterEpochSeconds, 64, "permit validAfter"));
    const deadline = BigInt(decimal(input.deadlineEpochSeconds, 64, "permit deadline"));
    if (validAfter > input.nowEpochSeconds || deadline <= input.nowEpochSeconds
      || deadline < validAfter
      || deadline - validAfter > ROUTER_V2_MAXIMUM_EXECUTION_PERMIT_SECONDS_V1
      || deadline > BigInt(walletIntent.expiresAtEpochSeconds)) {
      return permitDenial("PERMIT_WINDOW_INVALID");
    }
    const core = {
      schemaVersion: "programmable.router-v2-execution-permit.v1" as const,
      permitVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V1,
      planHash: plan.planHash,
      builderEvidenceHash: evidence.evidenceHash,
      reviewerAttestationHash: reviewerAttestation.attestationHash,
      profileDescriptorHash: descriptor.descriptorHash,
      exactContractBindingHash: binding.bindingHash,
      profileReleaseHash: binding.releaseHash,
      catalogHash: control.catalogHash,
      catalogGeneration: control.catalogGeneration,
      revocationGeneration: control.revocationGeneration,
      securityControlHeadHash: control.headHash,
      securityEpoch: control.securityEpoch,
      winnerKeyHash: sha256(input.winnerKeyHash, "permit winner key"),
      winnerReservationHash: winnerReservation.reservationHash,
      signerIoStartedAfterWinnerReservation: true as const,
      walletIntent,
      action,
      permitNonce: bytes32(input.permitNonce, "permit nonce"),
      contractPermitDigest: bytes32(input.contractPermitDigest, "contract permit digest"),
      validAfterEpochSeconds: validAfter.toString(10),
      deadlineEpochSeconds: deadline.toString(10),
      signerAuthorityBindingHash: sha256(
        input.signerAuthorityBindingHash,
        "signer authority binding",
      ),
      signatureArtifactSha256: sha256(
        input.signatureArtifactSha256,
        "permit signature artifact",
      ),
      residualPermitPolicy:
        "RECHECK_CURRENT_SECURITY_HEAD_BEFORE_SIGNER_IO_AND_BROADCAST" as const,
    };
    const permit = deepFreeze({
      ...core,
      permitHash: canonicalSha256(core.schemaVersion, core),
    });
    const decision = {
      authorityDecision: "ALLOW_BOUND_PERMIT" as const,
      denialCode: null,
      permit,
    };
    return deepFreeze({
      ...decision,
      decisionHash: canonicalSha256("programmable.router-v2-execution-permit-decision.v1", decision),
    });
  } catch {
    return permitDenial("ARTIFACT_MISMATCH");
  }
}

export function assertExecutionPermitStillCurrentV1(input: Readonly<{
  permit: ExecutionPermitV1;
  currentControlHead: SecurityControlHeadV1;
  nowEpochSeconds: bigint;
}>): Readonly<{ current: true; currentnessHash: Sha256Digest }> {
  const permit = assertExecutionPermitShapeV1(input.permit);
  const control = assertSecurityControlHeadV1(input.currentControlHead);
  if (control.globalKillSwitch
    || control.suspendedProfileDescriptorHashes.includes(permit.profileDescriptorHash)
    || control.securityEpoch !== permit.securityEpoch
    || control.catalogHash !== permit.catalogHash
    || control.catalogGeneration !== permit.catalogGeneration
    || control.revocationGeneration !== permit.revocationGeneration
    || BigInt(control.observedAtEpochSeconds) > input.nowEpochSeconds
    || BigInt(control.expiresAtEpochSeconds) <= input.nowEpochSeconds
    || input.nowEpochSeconds < BigInt(permit.validAfterEpochSeconds)
    || input.nowEpochSeconds >= BigInt(permit.deadlineEpochSeconds)) {
    throw new TypeError("residual execution permit is stale, suspended, revoked or killed");
  }
  const body = { permitHash: permit.permitHash, securityControlHeadHash: control.headHash };
  return deepFreeze({
    current: true as const,
    currentnessHash: canonicalSha256("programmable.router-v2-residual-permit-currentness.v1", body),
  });
}

export function createCanonicalLaunchReceiptV1(
  descriptorRaw: LaunchProfileDescriptorV1,
  planRaw: ApplicantLaunchPlanV1,
  permitRaw: ExecutionPermitV1,
  raw: Omit<CanonicalLaunchReceiptV1,
    "actionSchemaArtifactSha256" | "actionSchemaId" | "actionSelector" | "actionTypehash"
    | "builderEvidenceHash" | "capabilitySemantics" | "catalogGeneration" | "catalogHash"
    | "chainId" | "componentIdentities"
    | "contractPermitDigest" | "deploymentLineageHash" | "exactContractBindingHash"
    | "executionModule" | "executionModuleRuntimeCodeHash" | "feePolicyHash"
    | "launchClassification" | "launchId" | "permitAuthorityBindingHash" | "permitHash"
    | "planHash" | "planSchemaArtifactSha256" | "planSchemaId" | "profileDescriptorHash"
    | "profileReleaseHash" | "profileRevenueBindingHash" | "providerBindingHash"
    | "receiptHash" | "receiptStatus" | "receiptVersion" | "requiredComponentIdentityKinds"
    | "revenuePolicyHash" | "revocationGeneration" | "reviewerAttestationHash"
    | "reviewerDecision" | "schemaVersion" | "securityControlHeadHash" | "securityEpoch"
    | "templateBindingHash" | "transactionDataSha256"
    | "transactionSender" | "transactionTo" | "transactionValueWei"
    | "typedActionArtifactSha256">,
): Readonly<CanonicalLaunchReceiptV1> {
  exactKeys(raw, [
    "authenticatedReceiptEvidenceSha256", "blockHash", "blockNumber", "componentGraphHash",
    "configurationHash", "launchStampHash", "poolId", "poolKeyHash", "resultHash",
    "runtimeSetHash", "transactionHash", "transactionNonce",
  ], "canonical launch receipt input");
  const descriptor = assertLaunchProfileDescriptorV1(descriptorRaw);
  const plan = assertApplicantLaunchPlanV1(descriptor, planRaw);
  const permit = assertExecutionPermitShapeV1(permitRaw);
  const binding = descriptor.exactContractBinding;
  if (binding === null) throw new TypeError("launch receipt lacks an exact contract freeze");
  if (permit.planHash !== plan.planHash || permit.profileDescriptorHash !== descriptor.descriptorHash) {
    throw new TypeError("launch receipt permit crosses its exact plan");
  }
  const core = {
    schemaVersion: "programmable.router-v2-canonical-launch-receipt.v1" as const,
    receiptVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V1,
    permitHash: permit.permitHash,
    contractPermitDigest: permit.contractPermitDigest,
    planHash: plan.planHash,
    builderEvidenceHash: permit.builderEvidenceHash,
    reviewerAttestationHash: permit.reviewerAttestationHash,
    reviewerDecision: "APPROVED" as const,
    securityEpoch: permit.securityEpoch,
    securityControlHeadHash: permit.securityControlHeadHash,
    catalogHash: permit.catalogHash,
    catalogGeneration: permit.catalogGeneration,
    revocationGeneration: permit.revocationGeneration,
    launchId: plan.launchId,
    profileDescriptorHash: descriptor.descriptorHash,
    exactContractBindingHash: binding.bindingHash,
    profileReleaseHash: binding.releaseHash,
    profileRevenueBindingHash: binding.profileRevenueBindingHash,
    permitAuthorityBindingHash: binding.permitAuthorityBindingHash,
    capabilitySemantics: binding.capabilitySemantics,
    launchClassification: binding.launchClassification,
    requiredComponentIdentityKinds: binding.requiredComponentIdentityKinds,
    actionSelector: binding.actionSelector,
    actionTypehash: binding.actionTypehash,
    executionModule: binding.executionModule,
    executionModuleRuntimeCodeHash: binding.executionModuleRuntimeCodeHash,
    planSchemaId: binding.planSchemaId,
    planSchemaArtifactSha256: binding.planSchemaArtifactSha256,
    actionSchemaId: binding.actionSchemaId,
    actionSchemaArtifactSha256: binding.actionSchemaArtifactSha256,
    typedActionArtifactSha256: permit.action.typedActionArtifactSha256,
    chainId: permit.action.chainId,
    transactionHash: bytes32(raw.transactionHash, "launch transaction hash"),
    transactionSender: permit.action.from,
    transactionNonce: decimal(raw.transactionNonce, 64, "launch transaction nonce"),
    transactionTo: permit.action.to,
    transactionValueWei: permit.action.valueWei,
    transactionDataSha256: permit.action.transactionDataSha256,
    receiptStatus: "success" as const,
    blockNumber: positiveDecimal(raw.blockNumber, "launch block number"),
    blockHash: bytes32(raw.blockHash, "launch block hash"),
    componentGraphHash: bytes32(raw.componentGraphHash, "receipt component graph"),
    componentIdentities: plan.componentIdentities,
    runtimeSetHash: sha256(raw.runtimeSetHash, "receipt runtime set"),
    configurationHash: bytes32(raw.configurationHash, "receipt configuration"),
    poolKeyHash: nullableNonzeroBytes32(raw.poolKeyHash, "receipt pool key"),
    poolId: nullableNonzeroBytes32(raw.poolId, "receipt pool id"),
    resultHash: bytes32(raw.resultHash, "receipt result"),
    providerBindingHash: plan.providerBindingHash,
    templateBindingHash: plan.templateBindingHash,
    feePolicyHash: plan.feePolicyHash,
    revenuePolicyHash: plan.revenuePolicyHash,
    deploymentLineageHash: plan.deploymentLineageHash,
    launchStampHash: bytes32(raw.launchStampHash, "launch stamp"),
    authenticatedReceiptEvidenceSha256: sha256(
      raw.authenticatedReceiptEvidenceSha256,
      "authenticated launch receipt evidence",
    ),
  };
  if (core.componentGraphHash !== plan.componentGraphHash
    || core.runtimeSetHash !== plan.exactRuntimeSetHash
    || core.configurationHash !== plan.configurationHash
    || core.poolKeyHash !== plan.poolKeyHash
    || core.poolId !== plan.poolId
    || core.resultHash !== plan.resultHash) {
    throw new TypeError("canonical launch receipt does not reproduce its exact plan result");
  }
  return deepFreeze({ ...core, receiptHash: canonicalSha256(core.schemaVersion, core) });
}

