export function createFinalityIndexingReceiptV1(
  launchReceiptRaw: CanonicalLaunchReceiptV1,
  raw: Omit<FinalityIndexingReceiptV1,
    "appendOnlyStatus" | "canonicalLaunchReceiptHash" | "canonicalReceiptIdentityImmutable"
    | "chainId" | "launchStampHash" | "receiptHash" | "receiptVersion" | "schemaVersion"
    | "transactionHash">,
  previousReceiptRaw?: FinalityIndexingReceiptV1,
): Readonly<FinalityIndexingReceiptV1> {
  exactKeys(raw, [
    "dualProviderFinalityEvidenceSha256", "finalityObservedAt", "finalizedBlockHash",
    "finalizedBlockNumber", "indexedAt", "indexerAuthorityBindingHash", "indexingEvidenceSha256",
    "indexingStatus", "providerAuthoritySetHash", "supersedesReceiptHash",
  ], "finality and indexing receipt input");
  const launchReceipt = assertCanonicalLaunchReceiptShapeV1(launchReceiptRaw);
  const finalizedBlockNumber = positiveDecimal(raw.finalizedBlockNumber, "finalized block number");
  if (BigInt(finalizedBlockNumber) < BigInt(launchReceipt.blockNumber)) {
    throw new TypeError("finality anchor precedes the launch receipt");
  }
  const indexingStatus = raw.indexingStatus;
  if (!(["FINALIZED_PENDING_INDEXING", "FINALIZED_INDEXED"] as const).includes(indexingStatus)) {
    throw new TypeError("indexing status is invalid");
  }
  const indexerAuthorityBindingHash = raw.indexerAuthorityBindingHash === null
    ? null
    : sha256(raw.indexerAuthorityBindingHash, "indexer authority binding");
  const indexingEvidenceSha256 = raw.indexingEvidenceSha256 === null
    ? null
    : sha256(raw.indexingEvidenceSha256, "indexing evidence");
  const indexedAt = raw.indexedAt === null ? null : instant(raw.indexedAt, "indexing time");
  if (indexingStatus === "FINALIZED_INDEXED") {
    if (indexerAuthorityBindingHash === null || indexingEvidenceSha256 === null || indexedAt === null) {
      throw new TypeError("indexed finality receipt lacks authenticated indexing evidence");
    }
  } else if (indexerAuthorityBindingHash !== null || indexingEvidenceSha256 !== null || indexedAt !== null) {
    throw new TypeError("pending finality receipt contains unauthenticated indexing claims");
  }
  const core = {
    schemaVersion: "programmable.router-v2-finality-indexing-receipt.v1" as const,
    receiptVersion: ROUTER_V2_SHARED_LIFECYCLE_VERSION_V1,
    canonicalLaunchReceiptHash: launchReceipt.receiptHash,
    chainId: launchReceipt.chainId,
    transactionHash: launchReceipt.transactionHash,
    launchStampHash: launchReceipt.launchStampHash,
    finalizedBlockNumber,
    finalizedBlockHash: bytes32(raw.finalizedBlockHash, "finalized block hash"),
    providerAuthoritySetHash: sha256(raw.providerAuthoritySetHash, "provider authority set"),
    dualProviderFinalityEvidenceSha256: sha256(
      raw.dualProviderFinalityEvidenceSha256,
      "dual-provider finality evidence",
    ),
    finalityObservedAt: instant(raw.finalityObservedAt, "finality observation time"),
    indexingStatus,
    indexerAuthorityBindingHash,
    indexingEvidenceSha256,
    indexedAt,
    supersedesReceiptHash: raw.supersedesReceiptHash === null
      ? null
      : sha256(raw.supersedesReceiptHash, "superseded finality receipt"),
    canonicalReceiptIdentityImmutable: true as const,
    appendOnlyStatus: true as const,
  };
  if (core.supersedesReceiptHash === null) {
    if (previousReceiptRaw !== undefined) {
      throw new TypeError("initial finality receipt cannot name a predecessor object");
    }
  } else {
    if (previousReceiptRaw === undefined) {
      throw new TypeError("finality supersession lacks its exact predecessor receipt");
    }
    const previous = assertFinalityIndexingReceiptShapeV1(previousReceiptRaw);
    if (core.supersedesReceiptHash !== previous.receiptHash
      || previous.canonicalLaunchReceiptHash !== launchReceipt.receiptHash
      || previous.chainId !== core.chainId
      || previous.transactionHash !== core.transactionHash
      || previous.launchStampHash !== core.launchStampHash
      || previous.indexingStatus !== "FINALIZED_PENDING_INDEXING"
      || core.indexingStatus !== "FINALIZED_INDEXED"
      || previous.finalizedBlockNumber !== core.finalizedBlockNumber
      || previous.finalizedBlockHash !== core.finalizedBlockHash
      || previous.providerAuthoritySetHash !== core.providerAuthoritySetHash
      || previous.dualProviderFinalityEvidenceSha256
        !== core.dualProviderFinalityEvidenceSha256
      || previous.finalityObservedAt !== core.finalityObservedAt) {
      throw new TypeError("finality supersession is not an append-only status transition");
    }
  }
  return deepFreeze({ ...core, receiptHash: canonicalSha256(core.schemaVersion, core) });
}

export function assertFinalityIndexingReceiptV1(
  launchReceipt: CanonicalLaunchReceiptV1,
  raw: FinalityIndexingReceiptV1,
  previousReceipt?: FinalityIndexingReceiptV1,
): Readonly<FinalityIndexingReceiptV1> {
  const {
    appendOnlyStatus: _appendOnlyStatus,
    canonicalLaunchReceiptHash: _launchReceiptHash,
    canonicalReceiptIdentityImmutable: _canonicalReceiptIdentityImmutable,
    chainId: _chainId,
    launchStampHash: _stampHash,
    receiptHash: _receiptHash,
    receiptVersion: _receiptVersion,
    schemaVersion: _schemaVersion,
    transactionHash: _transactionHash,
    ...input
  } = raw;
  return exactArtifact(
    raw,
    createFinalityIndexingReceiptV1(launchReceipt, input, previousReceipt),
    "finality and indexing receipt",
  );
}

export type AuthorityWorkStageV1 =
  | "REVIEW_ADMISSION"
  | "JIT_CURRENTNESS"
  | "WINNER_RESERVATION"
  | "SIGNER_RECONCILIATION"
  | "BROADCAST_RECONCILIATION"
  | "FINALITY_RECONCILIATION"
  | "INDEXING_HANDOFF";

export interface AuthorityWorkItemV1 {
  readonly workId: string;
  readonly applicantFairnessKey: Sha256Digest;
  readonly planHash: Sha256Digest;
  readonly stage: AuthorityWorkStageV1;
  readonly enqueuedSequence: string;
  readonly notBeforeEpochSeconds: string;
  readonly attempt: string;
}

export interface AuthorityFairScheduleV1 {
  readonly schemaVersion: "programmable.router-v2-authority-fair-schedule.v1";
  readonly maximumConcurrency: 20;
  readonly activeCount: number;
  readonly previousFairnessCursor: Sha256Digest | null;
  readonly nextFairnessCursor: Sha256Digest | null;
  readonly selectedWorkIds: readonly string[];
  readonly deferredWorkIds: readonly string[];
  readonly schedulerHash: Sha256Digest;
}

export function scheduleAuthorityWorkFairlyV1(input: Readonly<{
  queued: readonly AuthorityWorkItemV1[];
  activeCount: number;
  nowEpochSeconds: bigint;
  fairnessCursor?: Sha256Digest | null;
}>): Readonly<AuthorityFairScheduleV1> {
  if (!Number.isSafeInteger(input.activeCount) || input.activeCount < 0
    || input.activeCount > ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1) {
    throw new TypeError("authority scheduler active count is invalid");
  }
  if (!Array.isArray(input.queued)
    || input.queued.length > ROUTER_V2_AUTHORITY_MAXIMUM_QUEUE_DEPTH_V1) {
    throw new TypeError("authority scheduler queue exceeds its closed bound");
  }
  const normalized = input.queued.map(normalizeAuthorityWorkItemV1);
  unique(normalized.map(({ workId }) => workId), "authority work ids");
  const ready = normalized.filter(({ notBeforeEpochSeconds }) =>
    BigInt(notBeforeEpochSeconds) <= input.nowEpochSeconds);
  const deferred = normalized.filter(({ notBeforeEpochSeconds }) =>
    BigInt(notBeforeEpochSeconds) > input.nowEpochSeconds);
  const groups = new Map<string, AuthorityWorkItemV1[]>();
  for (const item of ready) {
    const bucket = groups.get(item.applicantFairnessKey) ?? [];
    bucket.push(item);
    groups.set(item.applicantFairnessKey, bucket);
  }
  for (const bucket of groups.values()) {
    bucket.sort(compareWork);
  }
  let groupOrder = [...groups.entries()].sort((left, right) => {
    const oldest = compareWork(left[1][0]!, right[1][0]!);
    return oldest === 0 ? compareUtf8(left[0], right[0]) : oldest;
  });
  const previousFairnessCursor = input.fairnessCursor === undefined
    || input.fairnessCursor === null
    ? null
    : sha256(input.fairnessCursor, "authority fairness cursor");
  if (previousFairnessCursor !== null && groupOrder.length > 1) {
    const exactCursorIndex = groupOrder.findIndex(([key]) => key === previousFairnessCursor);
    const startIndex = exactCursorIndex >= 0
      ? (exactCursorIndex + 1) % groupOrder.length
      : Math.max(0, groupOrder.findIndex(([key]) => compareUtf8(key, previousFairnessCursor) > 0));
    groupOrder = [...groupOrder.slice(startIndex), ...groupOrder.slice(0, startIndex)];
  }
  const capacity = ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1 - input.activeCount;
  const selected: AuthorityWorkItemV1[] = [];
  while (selected.length < capacity && groupOrder.some(([, bucket]) => bucket.length > 0)) {
    for (const [, bucket] of groupOrder) {
      const next = bucket.shift();
      if (next !== undefined) selected.push(next);
      if (selected.length === capacity) break;
    }
  }
  const remaining = [...deferred, ...groupOrder.flatMap(([, bucket]) => bucket)]
    .sort(compareWork);
  const nextFairnessCursor = selected.at(-1)?.applicantFairnessKey ?? previousFairnessCursor;
  const core = {
    schemaVersion: "programmable.router-v2-authority-fair-schedule.v1" as const,
    maximumConcurrency: ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1 as 20,
    activeCount: input.activeCount,
    previousFairnessCursor,
    nextFairnessCursor,
    selectedWorkIds: Object.freeze(selected.map(({ workId }) => workId)),
    deferredWorkIds: Object.freeze(remaining.map(({ workId }) => workId)),
  };
  return deepFreeze({ ...core, schedulerHash: canonicalSha256(core.schemaVersion, core) });
}

export type AuthorityBackpressureDecisionV1 = Readonly<{
  decision: "ACCEPT" | "RETRY_AFTER" | "NOT_READY";
  retryAfterSeconds: string | null;
  reason: string;
  decisionHash: Sha256Digest;
}>;

export function evaluateAuthorityBackpressureV1(input: Readonly<{
  queueDepth: number;
  activeCount: number;
  durableStoreReady: boolean;
  oldestReadyAgeSeconds: string;
}>): AuthorityBackpressureDecisionV1 {
  if (!Number.isSafeInteger(input.queueDepth) || input.queueDepth < 0
    || !Number.isSafeInteger(input.activeCount) || input.activeCount < 0
    || input.activeCount > ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1) {
    throw new TypeError("authority backpressure counters are invalid");
  }
  const oldestAge = decimal(input.oldestReadyAgeSeconds, 64, "oldest ready work age");
  let decision: "ACCEPT" | "RETRY_AFTER" | "NOT_READY" = "ACCEPT";
  let retryAfterSeconds: string | null = null;
  let reason = "capacity-available";
  if (!input.durableStoreReady) {
    decision = "NOT_READY";
    reason = "durable-store-unavailable";
  } else if (input.queueDepth >= ROUTER_V2_AUTHORITY_MAXIMUM_QUEUE_DEPTH_V1) {
    decision = "RETRY_AFTER";
    retryAfterSeconds = "30";
    reason = "bounded-queue-full";
  } else if (input.activeCount === ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1
    && BigInt(oldestAge) >= 60n) {
    decision = "RETRY_AFTER";
    retryAfterSeconds = "5";
    reason = "all-workers-busy";
  }
  const core = { decision, retryAfterSeconds, reason };
  return deepFreeze({
    ...core,
    decisionHash: canonicalSha256("programmable.router-v2-authority-backpressure.v1", core),
  });
}

export interface WinnerReservationClaimV1 {
  readonly schemaVersion: "programmable.router-v2-winner-reservation-claim.v1";
  readonly winnerKeyHash: Sha256Digest;
  readonly planHash: Sha256Digest;
  readonly permitDigest: EvmBytes32V1;
  readonly idempotencyKeyHash: Sha256Digest;
  readonly reservationHash: Sha256Digest;
  readonly state: "CLAIMED_BEFORE_SIGNER_IO";
}

export interface AuthorityWinnerReservationStoreV1 {
  /** Must be one serializable/unique transaction. It is called before signer I/O. */
  reserveBeforeSignerIo(input: Readonly<{
    winnerKeyHash: Sha256Digest;
    planHash: Sha256Digest;
    permitDigest: EvmBytes32V1;
    idempotencyKeyHash: Sha256Digest;
  }>): Promise<Readonly<
    | { outcome: "CLAIMED"; claim: WinnerReservationClaimV1 }
    | { outcome: "IDEMPOTENT_REPLAY"; claim: WinnerReservationClaimV1 }
    | { outcome: "LOST_TO_EXISTING_WINNER"; claim: null }
  >>;
}

export interface AuthorityDurableLifecycleStoreV1 extends AuthorityWinnerReservationStoreV1 {
  enqueueIdempotently(item: AuthorityWorkItemV1): Promise<Readonly<AuthorityDurableRecordV1>>;
  loadByIdempotencyKey(
    idempotencyKeyHash: Sha256Digest,
  ): Promise<Readonly<AuthorityDurableRecordV1> | null>;
  compareAndSwap(
    expectedRecordHash: Sha256Digest,
    next: AuthorityDurableRecordV1,
  ): Promise<Readonly<{ outcome: "UPDATED" | "STALE"; record: AuthorityDurableRecordV1 }>>;
  parkRetryableOutage(input: Readonly<{
    expectedRecordHash: Sha256Digest;
    parkedState: "PARKED_PROVIDER_OUTAGE" | "PARKED_SIGNER_AMBIGUOUS";
    parkedReason: NonNullable<AuthorityDurableRecordV1["parkedReason"]>;
    retryNotBeforeEpochSeconds: string;
  }>): Promise<Readonly<AuthorityDurableRecordV1>>;
}

export interface AuthoritySignerPortV1 {
  /** Called only after a serializable winner claim has been durably persisted. */
  signReservedPermit(input: Readonly<{
    winnerReservation: WinnerReservationClaimV1;
    contractPermitDigest: EvmBytes32V1;
    idempotencyKeyHash: Sha256Digest;
  }>): Promise<Readonly<
    | { outcome: "SIGNED"; signatureArtifactSha256: Sha256Digest }
    | { outcome: "AMBIGUOUS_PARKED"; retryNotBeforeEpochSeconds: string }
    | { outcome: "PROVIDER_OUTAGE_PARKED"; retryNotBeforeEpochSeconds: string }
  >>;
  reconcileByIdempotencyKey(input: Readonly<{
    idempotencyKeyHash: Sha256Digest;
    signerRequestHash: Sha256Digest;
  }>): Promise<Readonly<
    | { outcome: "SIGNED"; signatureArtifactSha256: Sha256Digest }
    | { outcome: "NOT_FOUND_NO_RESIGN" }
    | { outcome: "STILL_AMBIGUOUS_PARKED"; retryNotBeforeEpochSeconds: string }
  >>;
}

export async function claimWinnerBeforeSignerIoV1(input: Readonly<{
  store: AuthorityWinnerReservationStoreV1;
  winnerKeyHash: Sha256Digest;
  planHash: Sha256Digest;
  permitDigest: EvmBytes32V1;
  idempotencyKeyHash: Sha256Digest;
}>): Promise<Readonly<WinnerReservationClaimV1> | null> {
  const request = {
    winnerKeyHash: sha256(input.winnerKeyHash, "winner key"),
    planHash: sha256(input.planHash, "winner plan"),
    permitDigest: bytes32(input.permitDigest, "winner permit digest"),
    idempotencyKeyHash: sha256(input.idempotencyKeyHash, "winner idempotency key"),
  };
  const result = await input.store.reserveBeforeSignerIo(request);
  if (result.outcome === "LOST_TO_EXISTING_WINNER") return null;
  const claim = assertWinnerReservationClaimV1(result.claim);
  if (claim.winnerKeyHash !== request.winnerKeyHash
    || claim.planHash !== request.planHash
    || claim.permitDigest !== request.permitDigest
    || claim.idempotencyKeyHash !== request.idempotencyKeyHash) {
    throw new TypeError("winner reservation store returned a crossed or counterfeit claim");
  }
  return claim;
}

export async function signAfterWinnerReservationV1(input: Readonly<{
  signer: AuthoritySignerPortV1;
  winnerReservation: WinnerReservationClaimV1;
  contractPermitDigest: EvmBytes32V1;
  idempotencyKeyHash: Sha256Digest;
}>): Promise<Awaited<ReturnType<AuthoritySignerPortV1["signReservedPermit"]>>> {
  const winnerReservation = assertWinnerReservationClaimV1(input.winnerReservation);
  const contractPermitDigest = bytes32(input.contractPermitDigest, "reserved signer permit digest");
  const idempotencyKeyHash = sha256(input.idempotencyKeyHash, "reserved signer idempotency key");
  if (winnerReservation.permitDigest !== contractPermitDigest
    || winnerReservation.idempotencyKeyHash !== idempotencyKeyHash) {
    throw new TypeError("signer request crosses its durable winner reservation");
  }
  const result = await input.signer.signReservedPermit({
    winnerReservation,
    contractPermitDigest,
    idempotencyKeyHash,
  });
  if (result.outcome === "SIGNED") {
    sha256(result.signatureArtifactSha256, "reserved signer signature artifact");
  } else {
    decimal(result.retryNotBeforeEpochSeconds, 64, "reserved signer retry time");
  }
  return deepFreeze(result);
}

export type AuthorityDurableStateV1 =
  | "QUEUED"
  | "LEASED"
  | "WINNER_RESERVED"
  | "SIGNER_IO_STARTED"
  | "SIGNED"
  | "BROADCAST_SUBMITTED"
  | "RECEIPT_OBSERVED"
  | "FINALIZED"
  | "INDEXED"
  | "PARKED_PROVIDER_OUTAGE"
  | "PARKED_SIGNER_AMBIGUOUS"
  | "REVOKED"
  | "FAILED_TERMINAL";

export interface AuthorityDurableRecordV1 {
  readonly recordHash: Sha256Digest;
  readonly workId: string;
  readonly idempotencyKeyHash: Sha256Digest;
  readonly state: AuthorityDurableStateV1;
  readonly revision: string;
  readonly leaseOwner: string | null;
  readonly leaseExpiresAtEpochSeconds: string | null;
  readonly signerRequestHash: Sha256Digest | null;
  readonly signerResponseHash: Sha256Digest | null;
  readonly transactionHash: EvmBytes32V1 | null;
  readonly parkedReason:
    | "RPC_UNAVAILABLE"
    | "PROVIDER_UNAVAILABLE"
    | "SIGNER_UNAVAILABLE"
    | "AMBIGUOUS_SIGNER_RESPONSE"
    | null;
  readonly retryNotBeforeEpochSeconds: string | null;
}

export type AuthorityRecoveryActionV1 =
  | "NOOP_TERMINAL"
  | "NOOP_ACTIVE_LEASE"
  | "KEEP_PARKED_RETRYABLE"
  | "REQUEUE_EXPIRED_LEASE"
  | "REQUEUE_PARKED_RETRYABLE"
  | "RECONCILE_SIGNER_BY_IDEMPOTENCY_KEY"
  | "PERSIST_SIGNED_RESPONSE_IDEMPOTENTLY"
  | "RECONCILE_BROADCAST_BY_FROM_NONCE_AND_HASH"
  | "RECONCILE_FINALITY_IDEMPOTENTLY"
  | "RECONCILE_INDEXING_HANDOFF_IDEMPOTENTLY";

export function planAuthorityCrashRecoveryV1(
  raw: AuthorityDurableRecordV1,
  nowEpochSeconds: bigint,
): Readonly<{ action: AuthorityRecoveryActionV1; recoveryHash: Sha256Digest }> {
  const record = normalizeAuthorityDurableRecordV1(raw);
  const expiredLease = record.leaseExpiresAtEpochSeconds !== null
    && BigInt(record.leaseExpiresAtEpochSeconds) <= nowEpochSeconds;
  let action: AuthorityRecoveryActionV1;
  switch (record.state) {
    case "QUEUED":
      action = "REQUEUE_EXPIRED_LEASE";
      break;
    case "LEASED":
    case "WINNER_RESERVED":
      action = expiredLease ? "REQUEUE_EXPIRED_LEASE" : "NOOP_ACTIVE_LEASE";
      break;
    case "SIGNER_IO_STARTED":
      action = "RECONCILE_SIGNER_BY_IDEMPOTENCY_KEY";
      break;
    case "SIGNED":
      action = "PERSIST_SIGNED_RESPONSE_IDEMPOTENTLY";
      break;
    case "BROADCAST_SUBMITTED":
      action = "RECONCILE_BROADCAST_BY_FROM_NONCE_AND_HASH";
      break;
    case "RECEIPT_OBSERVED":
      action = "RECONCILE_FINALITY_IDEMPOTENTLY";
      break;
    case "FINALIZED":
      action = "RECONCILE_INDEXING_HANDOFF_IDEMPOTENTLY";
      break;
    case "PARKED_PROVIDER_OUTAGE":
      action = BigInt(record.retryNotBeforeEpochSeconds!) <= nowEpochSeconds
        ? "REQUEUE_PARKED_RETRYABLE"
        : "KEEP_PARKED_RETRYABLE";
      break;
    case "PARKED_SIGNER_AMBIGUOUS":
      action = BigInt(record.retryNotBeforeEpochSeconds!) <= nowEpochSeconds
        ? "RECONCILE_SIGNER_BY_IDEMPOTENCY_KEY"
        : "KEEP_PARKED_RETRYABLE";
      break;
    case "INDEXED":
    case "REVOKED":
    case "FAILED_TERMINAL":
      action = "NOOP_TERMINAL";
      break;
  }
  const core = { recordHash: record.recordHash, action };
  return deepFreeze({
    action,
    recoveryHash: canonicalSha256("programmable.router-v2-authority-crash-recovery.v1", core),
  });
}

export interface AuthorityReconcilerV1 {
  requeueExpiredLeaseIdempotently(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  requeueParkedRetryableIdempotently(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  reconcileSignerByIdempotencyKey(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  persistSignedResponseIdempotently(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  reconcileBroadcastByFromNonceAndHash(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  reconcileFinalityIdempotently(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
  reconcileIndexingHandoffIdempotently(record: AuthorityDurableRecordV1): Promise<AuthorityReconcilerPortResultV1>;
}

export type AuthorityReconcilerPortResultV1 = Readonly<{
  outcome: "COMPLETED" | "PARKED_RETRYABLE";
  durableRecordHash: Sha256Digest;
}>;

export async function runAuthorityReconciliationV1(input: Readonly<{
  record: AuthorityDurableRecordV1;
  reconciler: AuthorityReconcilerV1;
  nowEpochSeconds: bigint;
}>): Promise<Readonly<{
  action: AuthorityRecoveryActionV1;
  outcome: "NOOP" | "IDEMPOTENT_RECONCILIATION_COMPLETED" | "PARKED_RETRYABLE";
  reconciliationHash: Sha256Digest;
}>> {
  const record = normalizeAuthorityDurableRecordV1(input.record);
  const recovery = planAuthorityCrashRecoveryV1(record, input.nowEpochSeconds);
  let portResult: AuthorityReconcilerPortResultV1 | null = null;
  switch (recovery.action) {
    case "NOOP_TERMINAL":
    case "NOOP_ACTIVE_LEASE":
    case "KEEP_PARKED_RETRYABLE":
      break;
    case "REQUEUE_EXPIRED_LEASE":
      portResult = await input.reconciler.requeueExpiredLeaseIdempotently(record);
      break;
    case "REQUEUE_PARKED_RETRYABLE":
      portResult = await input.reconciler.requeueParkedRetryableIdempotently(record);
      break;
    case "RECONCILE_SIGNER_BY_IDEMPOTENCY_KEY":
      portResult = await input.reconciler.reconcileSignerByIdempotencyKey(record);
      break;
    case "PERSIST_SIGNED_RESPONSE_IDEMPOTENTLY":
      portResult = await input.reconciler.persistSignedResponseIdempotently(record);
      break;
    case "RECONCILE_BROADCAST_BY_FROM_NONCE_AND_HASH":
      portResult = await input.reconciler.reconcileBroadcastByFromNonceAndHash(record);
      break;
    case "RECONCILE_FINALITY_IDEMPOTENTLY":
      portResult = await input.reconciler.reconcileFinalityIdempotently(record);
      break;
    case "RECONCILE_INDEXING_HANDOFF_IDEMPOTENTLY":
      portResult = await input.reconciler.reconcileIndexingHandoffIdempotently(record);
      break;
  }
  if (portResult !== null) sha256(portResult.durableRecordHash, "reconciled durable record");
  const outcome = portResult === null
    ? "NOOP" as const
    : portResult.outcome === "PARKED_RETRYABLE"
      ? "PARKED_RETRYABLE" as const
      : "IDEMPOTENT_RECONCILIATION_COMPLETED" as const;
  const core = { recordHash: record.recordHash, recoveryHash: recovery.recoveryHash, outcome };
  return deepFreeze({
    action: recovery.action,
    outcome,
    reconciliationHash: canonicalSha256(
      "programmable.router-v2-authority-reconciliation-result.v1",
      core,
    ),
  });
}

export type AuthoritySweepKindV1 =
  | "EXPIRED_LEASE"
  | "MISSED_RECEIPT_EVENT"
  | "FINALITY"
  | "INDEXING_HANDOFF";

export interface AuthoritySweepCandidateV1 {
  readonly cursor: string;
  readonly workId: string;
  readonly recordHash: Sha256Digest;
}

export function planAuthorityBoundedSweepV1(input: Readonly<{
  kind: AuthoritySweepKindV1;
  candidates: readonly AuthoritySweepCandidateV1[];
  afterCursor: string | null;
  maximumItems: number;
  fromPosition: string;
  toPosition: string;
}>): Readonly<{
  kind: AuthoritySweepKindV1;
  selected: readonly Readonly<AuthoritySweepCandidateV1>[];
  nextCursor: string | null;
  hasMore: boolean;
  sweepHash: Sha256Digest;
}> {
  const kinds: readonly AuthoritySweepKindV1[] = [
    "EXPIRED_LEASE", "MISSED_RECEIPT_EVENT", "FINALITY", "INDEXING_HANDOFF",
  ];
  if (!kinds.includes(input.kind)
    || !Number.isSafeInteger(input.maximumItems) || input.maximumItems < 1
    || input.maximumItems > ROUTER_V2_AUTHORITY_MAXIMUM_SWEEP_BATCH_V1
    || !Array.isArray(input.candidates)
    || input.candidates.length > ROUTER_V2_AUTHORITY_MAXIMUM_SWEEP_CANDIDATES_V1) {
    throw new TypeError("authority sweep exceeds its closed bound");
  }
  const fromPosition = decimal(input.fromPosition, 64, "sweep from position");
  const toPosition = decimal(input.toPosition, 64, "sweep to position");
  if (BigInt(toPosition) < BigInt(fromPosition)
    || BigInt(toPosition) - BigInt(fromPosition)
      > BigInt(ROUTER_V2_AUTHORITY_MAXIMUM_SWEEP_CANDIDATES_V1)) {
    throw new TypeError("authority sweep position window exceeds its closed bound");
  }
  const afterCursor = input.afterCursor === null
    ? null
    : safeId(input.afterCursor, "authority sweep cursor");
  const candidates = input.candidates.map((candidate) => {
    exactKeys(candidate, ["cursor", "recordHash", "workId"], "authority sweep candidate");
    return Object.freeze({
      cursor: safeId(candidate.cursor, "authority sweep candidate cursor"),
      workId: safeId(candidate.workId, "authority sweep candidate work id"),
      recordHash: sha256(candidate.recordHash, "authority sweep candidate record"),
    });
  }).sort((left, right) => compareUtf8(left.cursor, right.cursor));
  unique(candidates.map(({ cursor }) => cursor), "authority sweep candidate cursors");
  const remaining = candidates.filter(({ cursor }) =>
    afterCursor === null || compareUtf8(cursor, afterCursor) > 0);
  const selected = Object.freeze(remaining.slice(0, input.maximumItems));
  const nextCursor = selected.at(-1)?.cursor ?? afterCursor;
  const core = {
    kind: input.kind,
    afterCursor,
    maximumItems: input.maximumItems,
    fromPosition,
    toPosition,
    selected,
    nextCursor,
    hasMore: remaining.length > selected.length,
  };
  return deepFreeze({
    kind: core.kind,
    selected,
    nextCursor,
    hasMore: core.hasMore,
    sweepHash: canonicalSha256("programmable.router-v2-authority-bounded-sweep.v1", core),
  });
}

export interface AuthorityReadinessDependencyV1 {
  readonly name: string;
  readonly ready: boolean;
  readonly currentnessExpiresAtEpochSeconds: string;
  readonly bindingHash: Sha256Digest;
}

export interface AuthorityReadinessSnapshotV1 {
  readonly schemaVersion: "programmable.router-v2-authority-readiness-snapshot.v1";
  readonly ready: boolean;
  readonly maximumConcurrency: 20;
  readonly queueDepth: number;
  readonly activeCount: number;
  readonly dependencies: readonly Readonly<AuthorityReadinessDependencyV1>[];
  readonly reasons: readonly string[];
  readonly snapshotHash: Sha256Digest;
}

export const REQUIRED_ROUTER_V2_AUTHORITY_READINESS_DEPENDENCIES_V1 = Object.freeze([
  "currentness-provider",
  "durable-store",
  "finality-provider",
  "reconciler",
  "signer",
  "typed-action-verifier",
]);

export function createAuthorityReadinessSnapshotV1(input: Readonly<{
  queueDepth: number;
  activeCount: number;
  dependencies: readonly AuthorityReadinessDependencyV1[];
  nowEpochSeconds: bigint;
}>): Readonly<AuthorityReadinessSnapshotV1> {
  const pressure = evaluateAuthorityBackpressureV1({
    queueDepth: input.queueDepth,
    activeCount: input.activeCount,
    durableStoreReady: input.dependencies.find(({ name }) => name === "durable-store")?.ready ?? false,
    oldestReadyAgeSeconds: "0",
  });
  const dependencies = input.dependencies.map((dependency) => {
    exactKeys(dependency, ["bindingHash", "currentnessExpiresAtEpochSeconds", "name", "ready"],
      "authority readiness dependency");
    return Object.freeze({
      name: safeId(dependency.name, "readiness dependency name"),
      ready: strictBoolean(dependency.ready, "readiness dependency state"),
      currentnessExpiresAtEpochSeconds: decimal(
        dependency.currentnessExpiresAtEpochSeconds,
        64,
        "readiness dependency expiry",
      ),
      bindingHash: sha256(dependency.bindingHash, "readiness dependency binding"),
    });
  }).sort((left, right) => compareUtf8(left.name, right.name));
  unique(dependencies.map(({ name }) => name), "readiness dependency names");
  const reasons = REQUIRED_ROUTER_V2_AUTHORITY_READINESS_DEPENDENCIES_V1
    .filter((name) => !dependencies.some((dependency) => dependency.name === name))
    .map((name) => `${name}-missing`);
  reasons.push(...dependencies.flatMap((dependency) => {
    if (!dependency.ready) return [`${dependency.name}-not-ready`];
    if (BigInt(dependency.currentnessExpiresAtEpochSeconds) <= input.nowEpochSeconds) {
      return [`${dependency.name}-stale`];
    }
    return [];
  }));
  if (pressure.decision !== "ACCEPT") reasons.push(`backpressure-${pressure.reason}`);
  reasons.sort(compareUtf8);
  const core = {
    schemaVersion: "programmable.router-v2-authority-readiness-snapshot.v1" as const,
    ready: reasons.length === 0,
    maximumConcurrency: ROUTER_V2_AUTHORITY_MAXIMUM_CONCURRENCY_V1 as 20,
    queueDepth: input.queueDepth,
    activeCount: input.activeCount,
    dependencies: deepFreeze(dependencies),
    reasons: Object.freeze(reasons),
  };
  return deepFreeze({ ...core, snapshotHash: canonicalSha256(core.schemaVersion, core) });
}

